INSERT INTO `quest_objectives` (`ID`,`QuestID`,`Type`,`Order`,`StorageIndex`,`ObjectID`,`Amount`,`ConditionalAmount`,`Flags`,`Flags2`,`ProgressBarWeight`,`ParentObjectiveID`,`Visible`,`Description`,`VerifiedBuild`) VALUES (477135,98247,1,0,0,280179,1,1411409260,48,0,0.0,0,1,NULL,70862);
INSERT INTO `tmp_ruru_quest_template_locale` (`ID`,`LogTitle`,`LogDescription`,`QuestDescription`,`AreaDescription`,`PortraitGiverText`,`PortraitGiverName`,`PortraitTurnInText`,`PortraitTurnInName`,`QuestCompletionLog`) VALUES
(11,'Награда за гноллов из стаи Речной Лапы','Принесите 8 раскрашенных поручей гноллов в казармы заместителю судьи Рейнеру.','На границах Элвиннского леса появились гноллы – звероподобные твари, которым попросту нечего делать в этих краях. К югу от сторожевой башни была замечена большая группа этих существ: их слишком много, чтобы мы сумели с ними справиться. Хуже того: на востоке, у Озера Каменных Столбов, тоже обнаружили гноллов.$B$BАрмия Штормграда будет благодарна любому, кто поможет справиться с этой угрозой. В доказательство своей победы принеси мне раскрашенные нарукавные повязки гноллов.','','','','','',''),
(13,'Народное ополчение','Убейте 15 погромщиков и 15 мошенников из Братства Справедливости и вернитесь к Гриану Камнегриву на Сторожевой холм.','Шайка злобных погромщиков из Братства Справедливости разбойничает близ Прииска на Золотом Берегу, Луноречья и усадьбы Алекстона. Народное ополчение не потерпит этого. Разберись с этим немедленно, $n, и пусть весь Западный Край узнает о силе Света.$b$bЗолотой карьер находится неподалеку от побережья, к западу от башни. В качестве следующего этапа твоего обучения я хочу, чтобы ты $gубил:убила; 15 погромщиков и 15 мошенников из Братства Справедливости.','','','','','',''),
(19,'Тарил''зун','Принесите маршалу Маррису в Красногорье голову Тарил''зуна.','Вестники и отступники из клана Черной горы постоянно устраивают засады на дороге между городом и крепостью Каменной Стражи. Их предводитель – орк по имени Тарил''зун. Он уже натворил достаточно дел. Принеси мне его голову!','','','','','',''),
(20,'Угроза Черной горы','Принесите маршалу Маррису в Приозерье 10 иззубренных топоров.','К нам явились орки Черной Горы из Пылающих степей и захватили крепость Каменной стражи. Они грабят области к северу от Озер, и жители тех земель бежали в город, набились в него, словно сельди в бочку.$B$BПомоги Приозерью избавиться от этой угрозы. Перебей орков Черной Горы и принеси в доказательство десять иззубренных топоров.$B$BХотя орки теснят нас с севера, до нас доходили вести об их появлении и в юго-восточной части Красногорья. Если встретишь их – убивай без колебаний.','','','','','',''),
(34,'Незваный гость','Убейте Грубобрюха. Принесите Марти Джанроз клык вепря.','Мой сад снова разграблен и вытоптан. И я знаю, кто это сделал! Это проклятый вепрь, которого маршал Маррис прозвал Грубобрюхом.$B$BТеперь мне долго не удастся посадить нарциссы. Они загублены! И во всем виноват мерзкий кабан. Положи конец этому паразиту! Принеси мне его клык, и я с удовольствием вознагражу тебя. Говорят, он пасется в полях на юго-западе от Озер, но порой заходит и сюда, в мой сад.','','','','','',''),
(56,'Ночной дозор','Убейте 8 скелетов-воинов и 6 магов-скелетов по просьбе командира Алтеи Чернодрев.','Я – командир Ночного дозора, и мой долг – охранять покой жителей Темнолесья. Солдаты Штормграда оставили свои посты, предоставив нас самим себе.$b$bЕсли ты $gготов:готова; на подвиги, помоги нам! Отправляйся в Застывшие сады на юге от Темнолесья и убей 8 скелетов-воинов и 8 магов-скелетов. Мы должны дать отпор нежити!','','','','','',''),
(57,'Ночной дозор','Убейте 15 скелетов-губителей и 15 ужасных скелетов по просьбе командира Алтеи Чернодрев.','$n, я получила сведения о появлении нежити в наших лесах! Если ты не боишься, отправляйся на кладбище Вороньего холма и убей 15 скелетов-губителей и 15 ужасных скелетов. Также говорят, что скелеты появились и к югу от Темнолесья, на Безмятежном кладбище. Мы должны изгнать нежить из Сумеречного леса!','','','','','',''),
(58,'Ночной дозор','Убейте 20 распространителей чумы в восточном мавзолее Вороньего холма по просьбе командира Алтеи Чернодрев.','Обстановка на Вороньем холме не улучшилась. Безопасность Темнолесья – в твоих руках, $n. У нас не хватает стражей для обеспечения безопасности города. Придется тебе снова отправиться на Вороний холм и уничтожить 20 распространителей чумы в восточном мавзолее.','','','','','',''),
(64,'Забытая вещь','Верните фермеру Хмуроброву его карманные часы, которые находятся в платяном шкафу в его доме на тыквенной ферме на западе.','Это было ужасно! Верна разбудила меня, когда услышала гвалт в поле. Поля были полны хулиганья. Мы бежали в спешке, и я забыл взять с собой карманные часы. Папаша Верны подарил мне эти часы в день нашей с ней свадьбы, и мне прямо нехорошо от мысли, что ими могли завладеть те воры. Я оставил часы в доме, в платяном шкафу. Ищи тыквенную ферму к западу отсюда – ты ее не пропустишь. Если вернешь мне мои часы, я буду очень признателен!','','','','','',''),
(69,'Легенда о Сталване','Отправляйтесь в таверну "Гордость льва" и спросите, не слышал ли кто о Сталване.','Боже мой! Сразу и не заметил. В журнале, точно под первым адресом Сталвана, написан еще один адрес, частично вычеркнутый. Похоже, он направлялся в таверну "Гордость льва" в Златоземье. Можешь поискать сведения там, $n.','','','','','',''),
(74,'Легенда о Сталване','Отнесите страницу из дневника маршалу Хаггарду.','Внутри ящика вы находите много разных вещей: пыльные фамильные ценности, портрет, несколько охотничьих трофеев и старые книги. Уже на самом дне, под глиняной вазой, вам попадается страница, вырванная из дневника.','','','','','',''),
(89,'Мост Безмолвия','Принесите 5 железных пик и 5 железных клепок штейгеру Ослоу в Приозерье.','Из-за последнего нашествия орков нам пришлось переплавить весь металл на пули, мечи и доспехи. Мы посылали в Штормград за новыми поставками, но отряд гноллов Красногорья разграбил обоз и сбежал в холмы за Приозерьем.$b$BНам не хватает материалов на ремонт моста. Если ты принесешь мне 5 железных пик и 5 железных клепок, $n, я прикажу тебя наградить.$B$BЗа дело!','','','','','',''),
(91,'Закон Соломона','Принесите 10 подвесок Темношкуров помощнику судьи Конаху в ратушу Приозерья.','В восточных предгорьях нашего края обосновался враг Штормграда. С помощью тайной магии этот негодяй по имени Моргант сеет ужас и страдания в нашем городе и окрестностях.$b$bОн прибрал под свою руку гноллов из стаи Темношкуров, и они исполняют его повеления. Согласно Закону Озер, пособничество врагу королевства карается смертью.$b$bГноллов следует уничтожить!$b$bПринеси мне 10 подвесок Темношкуров и получишь награду.','','','','','',''),
(92,'Гуляш по-красногорски','Принесите Бреанне пять кусков жесткого мяса кондора, пять рыл больших сквернохряков и пять порций хрустящего паучьего мяса.','Я бы с радостью сделала для тебя гуляш по-красногорски, но есть небольшое затруднение. Во время недавнего вторжения орков мне пришлось кормить целый отряд солдат Штормграда, и все кладовые опустели... Хотя если ты снабдишь меня всеми необходимыми продуктами, я уж расстараюсь!$b$bПринеси мне пять кусков жесткого мяса кондора, пять рыл больших жутевепрей и пять порций хрустящего паучьего мяса.','','','','','',''),
(93,'Темные пирожки с крабами','Добудьте 6 липких паучьих лапок и принесите их шеф-повару Груалю в Темнолесье.','Открою тебе тайну: темные пирожки с "крабами" делаются из паучьих лапок! Понимаю, эта новость может быть для тебя неприятной, но пирожки получаются вкусные и ароматные – отличная закуска! Принеси мне липкие паучьи лапки, и я испеку для тебя пирожочки.$B$BГоворят, что лучшие лапки у ядовитых кругопрядов. Они плетут паутины на севере, между холмами и рекой.','','','','','',''),
(94,'Недремлющее Око','Отнесите амулет Азоры к статуе льва, стоящей рядом с башней Илгалара в Красногорье.','Мой соперник Моргант – волшебник, наделенный великой силой, но лишенный сердечной доброты. Он обосновался в башне Илгалара, что в Красногорье. Я нашел способ следить за ним при помощи Ока Азоры.$B$BОднако Око не дает возможности проникнуть в его мысли. Для такого дела мне потребуется помощь.$B$BЕсли ты согласишься помогать мне, возьми амулет Азоры и отнеси его к башне Илгалара. Амулет нужно положить под статую льва рядом с башней.$B$BЕсли это будет сделано, то с помощью силы Азоры я смогу проникнуть в замыслы Морганта.','','','','','',''),
(95,'Месть Свена','Выясните, что зарыто за старым пнем на ферме, где работал Свен.','Раньше я работал на одной из ферм на юго-востоке... а потом темные всадники спустились с перевала Мертвого Ветра и перебили всю мою семью, пока я был в отлучке!$B$BВернувшись, я увидел неподалеку от амбара неясную фигуру человека, который что-то закапывал. Он успел сбежать от меня, а задерживаться я не мог, потому что преследовал темных всадников. Так я и не узнал, что там спрятано.$B$BЕсли ты можешь выяснить, что закопал в землю этот незнакомец, я буду очень признателен. Поищи возле старого пня, рядом с амбаром.','','','','','',''),
(98,'Легенда о Сталване','Убейте Сталвана Мистмантла и принесите мадам Эве его фамильное кольцо.','Сталван Мистмантл вел порочную жизнь. От его руки погибли многие невинные люди. Несомненно, он виновен в бесчисленных преступлениях, а теперь угрожает и нашему Темнолесью. Лишь Свету известно, что за гнусные злодеяния он готовит. Ступай в его дом к северу от города, |3-6($c), и покончи со Сталваном раз и навсегда.$b$bПриведя мой приговор в исполнение, отправляйся к мадам Еве и покажи ей его фамильное кольцо. В конце концов именно ее предчувствие позволило нам раскрыть это темное преступление. Благодаря ей в Темнолесье стало безопаснее.','','','','','',''),
(101,'Тотем наказания','Принесите 10 клыков вурдалаков, 10 пальцев скелетов и 5 фиалов паучьего яда мадам Еве в Темнолесье.','По лесу расползается тление и порча, $n, и все мы вынуждены позаботиться о самозащите. Ветер несет мне вести о великой опасности, поджидающей тебя в ближайшем будущем.$b$bЕсли ты желаешь оградить себя от нее, $gблагородный:благородная:c; |3-6($c), принеси мне 10 клыков вурдалаков, 10 пальцев скелетов и 5 фиалов паучьего яда. Тогда я создам тотем Кары, который будет наносить урон тем, кто попытается напасть на тебя.','','','','','',''),
(115,'Темная магия','Принесите 3 полуночных сферы маршалу Маррису в Приозерье.','Орки из клана Черной Горы позвали на помощь чародеев, а те принесли с собой источники темной силы – полуночные сферы. Чародеи наносят чувствительные удары по защитникам Красногорья, и мы должны как можно скорее лишить их столь мощного оружия.$B$BДобудь для меня полуночные сферы. Ты найдешь их у чародеев Черной Горы. Я придумаю, как избавиться от Сфер, чтобы мир стал лучше и чище!','','','','','',''),
(116,'Засуха','Принесите кабатчику Дэниэлсу из Озер бочонок громоварского светлого из Западного края, бочонок "Мерло" из Штормграда, бутылку самогона из Темнолесья и бурдюк со сладким ромом из Златоземья.','Я в безвыходном положении, $n. Бутылки опустели, а новые поставки так и не пришли. Ох уж эти проклятущие орки.$b$bМожет, ты мне поможешь?$b$bЗабери бочонок "Мерло" в Штормграде, бутылку самогона в Темнолесье, бурдюк со сладким ромом в Златоземье и бочонок громоварского у Мрачнобуха. Он сейчас в южной части Западного края, в лагере у холмов Кинжалов. Принеси это все мне, и я тебя вознагражу.','','','','','',''),
(118,'Цена подков','Отнесите записку Вернера кузнецу Аргусу в Златоземье.','Я потратил так много железа на доспехи и оружие для стражников Штормграда, что теперь его не хватает даже на подковы для лошадей!$B$BОтнеси эту записку кузнецу Аргусу в Златоземье, я хочу попросить его прислать мне партию подков.','','','','','',''),
(120,'Гонец в Штормград','Мировой судья Соломон просит вас отнести отчет генералу Маркусу Джонатану в Штормград.','Тяжелые настали времена, |3-6($c). Город в непрерывной осаде. Если из Штормграда не пришлют подкрепление, нам не выстоять. Я доверяю тебе важнейшее письмо. Отнеси его в Штормград генералу Маркусу Джонатану. И поскорее возвращайся с вестями – неважно, добрыми или злыми.$b$bСпеши!','','','','','',''),
(121,'Посланец в Штормград','Отнесите ответ генерала Маркуса Джонатана мировому судье Соломону в Приозерье.','Пока я жду ответа от короля, хочу, чтобы ты $gотнес:отнесла; это письмо мировому судье Соломону. $B$B$GСвободен:Свободна;, |3-6($c)!','','','','','',''),
(124,'Лай гноллов','Убейте 10 громил из стаи Красногорья и 8 мистиков из стаи Красногорья. Вернитесь к Вернеру Осгуду.','Будто нам одних орков мало! А теперь вдоль хребта рядом с моими стойлами шастают громилы и мистики гноллов и при случае воруют лошадей…$B$BЕсли ты сможешь избавить меня от этих проходимцев, мы с лошадьми будем весьма признательны.','','','','','',''),
(125,'Утраченные инструменты','Достаньте ящик с инструментами штейгера Ослоу со дна Озера Безмолвия.','Мне не помешала бы помощь, $n. Наш город в осаде, и достать припасы и оборудование все труднее. Мои инструменты везли из Златоземья в фургоне, но мост был уничтожен. Мы перегрузили их в лодку, но тут орки пробили ее снарядом из катапульты! И вот невезенье, ящик опустился на самое дно озера.$b$bДостань его, $n, и я щедро вознагражу тебя.','','','','','',''),
(126,'Вой в холмах','Принесите лапу Изувоя Вернеру Осгуду в Приозерье.','$n, гноллы по-прежнему здесь. Я слышу, как они завывают, охотясь в холмах над Приозерьем. И один из них воет громче других – это Изувой, их вождь.$B$BСтоит его прикончить, и вся стая разбежится! Убей его и принеси в доказательство отрубленную лапу.$B$BСоблюдай осторожность,  этот гнолл заслуженно возглавляет целую стаю. Он совсем не прост...','','','','','',''),
(127,'Продажа рыбы','Принесите 10 тушек пятнистой рыбы-луны портовому начальнику Барену в Приозерье.','Застывшее озеро славится пятнистой рыбой-луной. На нее всегда есть спрос... А мой запас подходит к концу!$B$BПринеси мне штук десять рыбин, и я хорошо за них заплачу. Если ты $gсам:сама; не умеешь удить, то... Попытайся отнять рыбу у мурлоков!','','','','','',''),
(128,'Награда за головы орков Черной горы','Убейте 15 воителей из клана Черной горы.','Мы должны уничтожить клан Черной Горы. Враг вторгся в наши земли. Эти горы по праву принадлежат королю Штормграда. До нас дошли сведения, что главы всех видов войск клана называются воителями. Их можно отыскать в северном лагере, к западу от дороги, ведущей в Пылающие степи.$b$bМировой судья Соломон распорядился перебить этих гнусных тварей. Убей 15 воителей из клана Черной Горы и возвращайся ко мне.','','','','','',''),
(129,'Бесплатный обед','Отнесите обед стражнику Паркеру. Он патрулирует дорогу, ведущую в Темнолесье.','Можешь оказать мне услугу? Я приготовила обед для стражника Паркера, но он ушел на дежурство... Он-то может постоять за себя, но простой горожанке вроде меня не стоит соваться в те края.$B$BЕсли ты отнесешь ему обед, я бесплатно тебя накормлю! Паркер патрулирует участок дороги, ведущей в Сумеречный лес.','','','','','',''),
(130,'Визит к травнице','Поговорите с травницей Красногорья Марти Джайнроз.','Если ты все равно идешь к Дарси, не отнесешь ли ей от меня цветы? Букетик можно приобрести у травницы в Приозерье, в западной части города.$B$BТолько когда будешь покупать цветы… не говори травнице Марти, от кого они и кому...','','','','','',''),
(131,'Доставка нарциссов','Отнесите Дарси букет нарциссов.','Вот и букет. Я выбрала для тебя нарциссы. Мои любимые цветы!','','','','','',''),
(132,'Братство Справедливости','Отнесите записку Вилли Гриану Камнегриву в Западный Край.','То, о чем я хочу вам рассказать, может стоить мне жизни. Бандиты из Братства Справедливости замышляют что-то крупномасштабное. Последнее, что я слышал, – что они действуют заодно со всякими гноллами, кобольдами и даже гоблинами.$b$bОтнеси эту записку Камнегриву. В ней разъясняется все, что я знаю на эту тему.','','','','','',''),
(140,'Спрятанное сокровище капитана Сандерса','Установите местонахождение сундука капитана Сандерса и откройте его.','Конечно же, глубоко внутри старого кувшина лежит еще одна подсказка к поиску сокровища Сандерса. Чернила кое-где расплылись, а бумага отдает виски, но кое-что вам удалось разобрать: "Раз уж ты $gнашел:нашла; мой старый кувшин из-под виски, значит, ты близко $gподобрался:подобралась; к сокровищу! Иди от бутылки на запад и спустись к берегу. Доберешься до воды – не останавливайся! Плыви, пока не найдешь остров, где и находится мой сундук с сокровищем!','','','','','',''),
(143,'Гонец в Западный Край','Отнесите просьбу о помощи Гриану Камнегриву в Западный Край.','Что-то странное происходит в армии Штормграда, подкрепления все нет и нет. К сожалению, мы не можем позволить себе ждать. Нельзя же сидеть сложа руки и не пытаться позвать соседей на помощь, пока доблестные воины Приозерья погибают один за другим. Говорят, в Западном Крае создано народное ополчение.$b$bОтнеси мою просьбу о помощи его предводителю, Гриану Камнегриву. Может быть, его люди помогут нам продержаться до подхода королевских отрядов.','','','','','',''),
(145,'Гонец в Темнолесье','Отнесите письмо лорду Чернодреву в Темнолесье.','И снова мне нужна твоя помощь. Я написал письмо лорду Чернодреву, прося его прислать нам на помощь обученных бойцов Ночного дозора на защиту Озер. Надо как можно скорее доставить мое послание. Действуй осторожно. Лорд Чернодрев – мэр города Темнолесья, расположенного в сердце Сумеречного леса. Не сходи с дороги.','','','','','',''),
(149,'Прядь призрачных волос','Отнесите Слепой Мэри призрачный гребень.','На старой ферме, в холмах к югу от Темнолесья, живет несчастное привидение по имени Слепая Мэри.$B$BВозьми этот призрачный гребень и попроси Слепую Мэри расчесать волосы. Потом принеси гребень обратно, и я сниму с него призрачные волосы, необходимые для нити.$B$BБудь $gосторожен:осторожна;, рядом с домом бродит множество темных тварей.','','','','','',''),
(150,'Мурлоки-браконьеры','Принесите 8 плавников мурлоков портовому начальнику Барену в Приозерье.','Мурлоки начинают нас беспокоить. Все больше мурлокских рыбаков селится вдоль побережья Озера Безмолвия и вовсю ловит рыбу! Надо изгнать их, пока они не опустошили все озеро!$B$BУбей побольше мурлоков! Принеси мне восемь их плавников, и я найду, чем тебе отплатить...','','','','','',''),
(159,'Доставка сока','Отнесите сок зомби в хижину Аберкромби.','А вот и сок зомби…$B$BБудь с ним $Gосторожен:осторожна;. Он такой крепкий, что мертвого поднимет!','','','','','',''),
(163,'Вороний холм','Выясните, кто поселился на Вороньем холме.','Что-то неладно на Вороньем холме, $n. Калор клянется, что он заметил кого-то – или что-то – в одном из домов. Две ночи подряд он видел крадущиеся тени, а на третью – свет в одном из окон.$b$bЕсли тебя и в самом деле беспокоит безопасность Темнолесья, выясни, что за чудовище скрывается на Вороньем холме.','','','','','',''),
(164,'Припасы для Свена','Отнесите Свену припасы.','Ты знаешь Свена? Вот кто настоящий служитель Света! Он и его последователи стоят лагерем в северо-западной части Сумеречного леса.$b$bУвы, их так мало, что некого отправить за припасами в город. Не поможешь ли ты ему?','','','','','',''),
(165,'Отшельник','Навестите старика в хижине рядом с кладбищем Вороньего холма.','Одно время в город частенько приходил старик и покупал припасы, но в последнее время я его не видела. Он живет в хижине рядом с кладбищем Вороньего холма, если я верно запомнила. Не навестишь ли ты его? Вдруг с ним что-то случилось?','','','','','',''),
(166,'Братство Справедливости','Убейте Эдвина ван Клифа и принесите его голову Гриану Камнегриву.','Осталось одно, последнее задание. Эдвин ван Клиф должен умереть. Хотя меня печалит сам факт вынесения человеку смертного приговора, для всего народа Западного Края будет гораздо лучше, если ван Клиф упокоится навечно. Принесите мне голову этого негодяя, когда с ним будет покончено.','','','','','',''),
(167,'О, брат мой...','Принесите значок Лиги Исследователей, принадлежавший штейгеру Чертополоху в Штормград.','Мы находились в обширных шахтах Западного Края, скрытых глубоко под землями Луноречья. Понятия не имею, откуда явились эти мерзкие вороватые вонючки. Так или иначе – туннель обрушился на нас. Мне удалось выбраться, но остальные... о них я ничего не знаю.$b$bВдруг тебе повезет больше, чем мне? Я ищу своего брата. Он всегда носил значок Лиги Исследователей. Если ты не найдешь брата, постарайся найти хотя бы его значок.','','','','','',''),
(168,'Сбор воспоминаний','Добудьте 4 карточки Союза шахтеров и верните их Дикому Чертополохху в Штормград.','Многие из моих друзей погибли в тот роковой день, когда обрушился штрек. Если тебя как-нибудь занесет в ту шахту в Луноречье, пожалуйста, постарайся добыть что-то, что поможет их опознать. А если найдешь их карточки Союза шахтеров, принеси их мне, я отправлю их семьям погибших.','','','','','',''),
(169,'РАЗЫСКИВАЕТСЯ: Гат''Илзогг','Убейте Гат''Илзогга и принесите его голову мировому судье Соломону в Приозерье.','Розыск! Гат''Илзогг, вождь клана Черной Горы, разыскивается за нападение на крепость Каменной Стражи и набеги на окрестности Приозерья. $b$bГат''Илзогг крайне опасен. По последним сведениям, он находится в недавно захваченной крепости и замышляет новые преступления против Королевства. Нашествие орков должно быть остановлено любой ценой. Храбрец, доставивший голову Гат''Илзогга мировому судье  Соломону, будет щедро вознагражден.','','','','','',''),
(173,'Воргены в лесу','Калор из Темнолесья просит вас убить 6 тенеткачей Ночной Погибели.','На Сумеречный лес наступают силы тьмы, и цель мастера Кэрвина – борьба с этим злом. Благодаря нашим усилиям народ Темнолесья живет в безопасности.$b$bТы считаешь, что $gдостоин:достойна; вступить в наши ряды?$b$bКогда-то я был таким же, как ты. Меня раздражало самодовольство Дозора, и я стал соратником мастера Кэрвина. Если ты хочешь показать, на что $gспособен:способна;, то слова тебе не помощники.$b$bВыступи против воргенов-тенеткачей Ночной Погибели в Светлой роще – светлой, ха! – и Гниющем саду.','','','','','',''),
(176,'РАЗЫСКИВАЕТСЯ: "Дробитель"','Убейте Дробителя и принесите маршалу Дугхану большой коготь гнолла.','Разыскивается: Дробитель$B$BВ юго-западной части Элвиннского леса поселился могучий гнолл по прозванию Дробитель. Несмотря на все усилия, поймать его так и не удалось.$B$BАрмия Штормграда назначила за этого гнолла щедрую награду. Чтобы получить ее, необходимо представить маршалу Дугхану доказательства смерти Дробителя.','','','','','',''),
(178,'Поручение Теокрита','Принесите выцветшую подвеску Темношкуров верховному магу Теокриту.','*До вас доносится бесплотный голос...*$B$BНе пугайся. Я Теокрит, верховный маг башни Азоры в Элвиннском лесу. При помощи этой подвески гноллы из стаи Темношкуров общаются со своим повелителем Моргантом.$B$BЯ потратил много времени на то, чтобы тоже научиться вещать через эти подвески. Если ты слышишь мое сообщение, значит заклинание сработало.$B$BПринеси мне эту подвеску, и я щедро вознагражу тебя.','','','','','',''),
(180,'РАЗЫСКИВАЕТСЯ: лейтенант Фангор','Убейте лейтенанта Фангора и принесите его лапу мировому судье Соломону в Приозерье.','Разыскивается: лейтенант Фангор$b$bГлава гнолльской стаи Темношкуров, соратник Морганта, врага Города и Королевства. По приказу чиновника Соломона подлый предатель Штормграда приговаривается к смерти. Тот, кто приведет приговор в исполнение, должен в доказательство принести лапу Фангора мировому судье Соломону.','','','','','',''),
(181,'Взгляни на звезды','Отыщите Ззарк''Вула в кургане на юге Сумеречного леса и принесите его монокль Виктору в Темнолесье.','Для завершения работы не хватает только одного предмета. Согласно чертежам Кога, нам нужна линза. Единственную подходящую линзу в наших краях будет нелегко достать.$B$BВ кургане на юге Сумеречного леса живет огр по имени Ззарк''Вул. Если сможешь, принеси мне его монокль, и я использую его вместо линзы!','','','','','',''),
(214,'Красные шелковые банданы','Принесите 10 красных шелковых бандан разведчице Риэле к башне на Сторожевом холме.','Не секрет, что красные банданы являются отличительным знаком бандитов из Братства Справедливости. Но мы узнали, что материал, из которого они изготовлены, указывает на ранг члена братства.$b$bЯ рассказываю вам об этом, потому что хочу, чтобы вы устранили как можно больше бандитов высокого ранга. Обладающих наивысшим рангом, без сомнения, можно найти в тайном убежище ван Клифа. Когда справитесь с заданием, принесите мне 10 красных шелковых бандан в доказательство их смерти – и будете вознаграждены. Желаю удачи, $n.','','','','','',''),
(219,'Пропавший без вести','Проводите капрала Кеешана до Красногорья.','Наконец-то, сторонники Альянса!$b$bПомогите... Пожалуйста...$b$bПоследнее, что я помню – как орки окружили наш отряд. Меня ударили по затылку, и в глазах потемнело. А теперь я пленник в этой пещере. Спасите меня, я тяжело ранен.$b$bМне понадобится помощь, чтобы добраться до города... Пожалуйста... Вы моя последняя надежда...','Проводите капрала Кеешана до Красногорья.','','','','',''),
(221,'Воргены в лесу','Убейте 12 вестников Тьмы из стаи Ночной Погибели.','Может, ты $gзаметил:заметила; крупных воргенов, бродящих по лесу в компании тенеткачей? Судя по всему, большую часть воргенских сил и составляют эти самые вестники Тьмы.$b$bСтранствуя по лесу, я узнал, что они захватили и Гниющий сад на юго-западе от города. Эти воргены сильнее тех, с которыми тебе уже пришлось столкнуться.$b$bБудь $gосторожен:осторожна;.','','','','','',''),
(245,'Восьминогая угроза','Убейте 15 карликовых ядовитых кругопрядов и доложите об этом дозорному Додсу в Сумеречном лесу.','Привет тебе, |3-6($c). Наверное, ты $Gвидел:видела; пауков на западной границе? Эти восьминогие чудища нам не по зубам, а командир не может отпустить солдат так далеко от Темнолесья.$b$bМне неловко просить тебя о помощи, но, кажется, тебе удалось бы с ними разобраться. Не могу обещать тебе большую награду, но одарю, чем смогу, если ты поможешь извести этих гадов.$b$bМой тебе совет: остерегайся их яда.','','','','','',''),
(246,'Подсчет врагов','Убейте 10 полукровок из стаи Красногорья и 6 браконьеров из стаи Красногорья и сообщить об этом заместителю судьи Фелдону в Приозерье.','У нас нет лишних людей, но с гноллами, о которых ты говоришь, надо что-то делать.$B$BПоищи их в южной части Красногорья. Убей, кого сможешь, и сообщи мне об их общем числе и степени угрозы, которую они представляют для города. Гноллы стоят лагерем вдоль южной дороги.$B$BСделай это ради армии Штормграда, $n, и получишь награду.','','','','','',''),
(248,'Пронизывающий взор','Поднимитесь на уцелевшую башню рядом с крепостью Каменной Стражи.$b$bОтыщите подходящее место и спрячьте там амулет Азоры.','Я наблюдал за башней Илгалара и понял, что Моргант враждует с орками крепости Каменной Стражи. Не знаю, что за этим кроется, но ты можешь помочь мне приоткрыть завесу тайны.$B$BВозьми еще один амулет Азоры и отнеси его на вершину уцелевшей башни рядом с крепостью.$B$BОтыщи подходящее место для амулета и спрячь его там. Для этой цели прекрасно подойдет сундук или кувшин.','','','','','',''),
(249,'Моргант','Победите Морганта.$B$bПринесите его подвеску Тени Теокриту в башню Азоры в Элвиннском лесу.','Ценой долгих усилий я раскрыл планы Морганта.$B$BОн ищет Косу Элуны... и быть может, уже отыскал ее! Коли так, то скоро Красногорье, а следом и все королевство Штормграда почувствует его темную мощь.$B$BЯ не готов выступить против Морганта, но, боюсь, терять время нельзя. Ты $gдолжен:должна; войти в башню Илгалара и бросить ему вызов.$B$BОдолей злодея, принеси мне его подвеску Тени, и королевство тебя не забудет.','','','','','',''),
(255,'Наемники','Мировой судья Тупонос просит вас убить 4 огров из клана Мо''грош, 4 громил из клана Мо''грош и 4 головорезов из клана Мо''грош.','Пройдет два месяца, прежде чем из Стальгорна к нам на подмогу направят горстку солдат, да еще два месяца они будут до нас добираться! И мало того, что наш город остался без защиты, но раскоп и дамба – дамба! – тоже в опасности.$b$bПохоже, у меня нет выбора. Придется искать наемников.$b$bКак насчет тебя? На первый взгляд ты подходишь, |3-6($c). На северном берегу озера разбила лагерь группа огров. Может быть, ты избавишь наш город от опасности?','','','','','',''),
(256,'Разыскивается: Чок''сул','Убейте Чок''сула и принесите его голову чиновнику Тупоносу в Телcамар.','По приказу магистрата Телcамара:$b$bЧок-сул, обвиняемый в организации нападений на город Телcамар, Каменную дамбу и раскоп, приговаривается к смерти любым из возможных способов.$b$bВознаграждение получит тот, кто предоставит в Магистрат доказательства смерти Чок-сула.$b$bВ последний раз обвиняемого видели в лагере огров в северо-восточной части озера Лок Модан.','','','','','',''),
(269,'В поисках мудрости','Отдайте законченные записи Трясунчика епископу Фартингу в Штормграде.','Отправляйся в Штормград и поговори с епископом Фартингом в Соборе Света. Отдай ему записи Трясунчика и сообщи, что собираешься бросить вызов Морбенту Скверну.$B$BХоть Штормград и бросил Темнолесье на произвол судьбы, Фартинг – добрая душа и мудрый человек. Он поможет тебе спасти нас.$B$BТебя ждет много опасностей... Однако поспеши, $n. С каждым часом в Сумеречном лесу сгущается тьма.','','','','','',''),
(276,'Вытоптанные луга','Убейте 15 гноллов  из стаи Мохошкуров и 10 полукровок  из стаи Мохошкуров. Вернитесь к Ретилю Стражу Природы в Болотину.','Многие годы гноллы из стаи Мохошкуров мирно жили в Болотине, но теперь их поголовье увеличилось. Они вытаптывают наши прекрасные луга и вырубают лес на дрова!$B$BЧтобы спасти природу нашего края, придется истребить часть гноллов.$B$BУбей 15 гноллов из стаи Мохошкуров и 10 полукровок из стаи Мохошкуров. Они водятся на юге, возле дворфийских Врат Альгаза. Когда справишься с заданием, вернись ко мне.','','','','','',''),
(277,'Запрет на огонь','Принесите Ретилю Стражу Природы 9 необработанных кремней.','Гноллы из стаи Мохошкуров вырубают деревья Болотины и жгут древесину, греясь у костров. Я этого не потерплю!$B$BОтбери у гноллов их кремни, которыми они высекают огонь. Кремни есть у всего клана, кроме мелких гноллов и полукровок из стаи Мохошкуров.','','','','','',''),
(279,'Угроза из глубин','Убейте 12 мурлоков из племени Синежабрых.$B$BПрикончите Жруна и принесите его голову Карлу Борану в Гавань Менетилов.','Мурлоки выходят из морских глубин и строят свои поселения на побережье. Они нападают на наших рыбаков и торговцев, и это уже переходит всякие границы. Их надо остановить.$B$BОдин из этих мурлоков, Жрун, придумал устраивать засады на наших купцов на дорогах. На мурлоков из племени Синежабрых нет никакой управы. Творят, что хотят, а потом прячутся в ближайших поселениях, и все – их уже не достать. Наши торговцы в опасности, и мы готовы хорошо заплатить тому, кто возьмется их защищать.$B$BЖрун промышляет в речном заливе к северу отсюда. Принеси мне его голову, а заодно перебей его сородичей.','','','','','',''),
(289,'Проклятая команда','Убейте 13 проклятых матросов, 5 проклятых стражей бухты и первого помощника Снеллига. Принесите табакерку Снеллига первому помощнику Фитсиммонсу в Гавань Менетилов.','<Приободрившись, Фитсиммонс продолжает рассказывать...>$B$BЯ единственный уцелевший из всех матросов злополучной кул-тирасской Третьей флотилии, погибшей у северного побережья. И хотя я последний из команды, чье сердце бьется и кто еще дышит, я не единственный, кто еще бродит по земле! На одном из наших кораблей хранилось великое, ужасное сокровище, и его потусторонняя зловещая сила удерживает души моих собратьев, не давая им покинуть гниющие остовы кораблей.$B$BЕсли ты сможешь их освободить, тогда, может быть, они избавятся от проклятия.','','','','','',''),
(297,'Сбор идолов','Принесите Магмару Рудоколу 8 резных каменных идолов.','Незадолго до появления в раскопе троггов мы обнаружили множество странных резных идолов. Изучить их мы не успели, потому что вскоре после этого трогги вытеснили нас из развалин! А идолы оказывают на этих тварей странное воздействие – превращают их в берсерков!$B$BОтбей идолов у троггов и принеси мне – я хочу их изучить. Идолов ты найдешь у троггов – а их в раскопе более чем достаточно.','','','','','',''),
(303,'Война с Черным Железом','Мотли Каменщик в Дун Модре просит вас убить 15 дворфов, 5 проходчиков, 5 саботажников и 5 подрывников из клана Черного Железа.','Война свирепствует повсюду: и в наших краях, и в чужих землях тоже. Пока наши могучие воины не щадят своих жизней, сражаясь во имя Альянса вдали от дома, на наших собственных землях бесчинствуют дворфы Черного Железа. Они разрушили один из мостов Тандола, потом пал и Дун Модр.$b$bТебе нужно собрать добровольцев и сдержать натиск врагов. Если сумеешь убить 10 дворфов Черного Железа, 5 проходчиков, 5 саботажников и 5 подрывников, тогда, может быть, мы и продержимся до подхода подкрепления.$b$bИ поторопись! У нас мало времени.','','','','','',''),
(304,'Мрачное поручение','Убейте Балгараса Нечистого и принесите его ухо Гриму Длинной Косе в Дун Модр.','Сколько наших полегло в битве при Дун Модре! Мой родной брат погиб, когда обрушился западный мост Тандола. Да, дворфы Черного Железа – те еще бестии. Чертово племя, шайка головорезов. Рогго сумел разузнать, что их предводитель в Болотине – некий чернокнижник по имени Балгарас Нечистый. Трус и мерзавец, каких поискать. Посылает на битву своих солдат, а сам прячется у себя в лагере на Зловещем холме, к юго-востоку отсюда.$b$bРазыщи этого подлого слизняка, убей его, принеси мне его ухо, и получишь награду, |3-6($c).','','','','','',''),
(305,'Пропавшие ученые','Таррел Камнепряд просит отыскать Меррин Камнепряд на раскопках.','Знаешь... как-то мне неспокойно на сердце.$b$bМоя благоверная Меррин работает в изыскательской группе на раскопе Вельгара. Писала мне каждую неделю весь прошлый месяц. А теперь вдруг пропала. Уже две недели ни слуху, ни духу. Наверняка что-то случилось!$b$bДлинная Коса обещал, что, если я вскорости не получу никаких известий, он пришлет мне разведчика, который проверит, что стало с экспедицией. Как я понимаю, ты и есть этот разведчик, $n. Разыщи Меррин на раскопе к востоку отсюда!','','','','','',''),
(321,'Светлосталь','Найдите груз с затонувшего корабля "Орлик" в Болотине.','Эти обломки погибших кораблей – останки Кул-Тирасской Третьей флотилии, сожженной и потопленной красными драконами во время последней Великой войны.$B$BФлотилия вышла из Лордерона, и с ней шел эльфийский боевой корабль – "Орлик". Он вез груз светлостали и присоединился к Третьей флотилии, ища покровительства и защиты. По иронии судьбы, он был потоплен теми же драконами, от которых пытался спастись...$B$BЛадно, краткий исторический экскурс будем считать завершенным. "Орлик" затонул к югу от Гавани Менетилов. Если найдешь светлосталь, принеси ее мне.','','','','','',''),
(335,'Благородный напиток','Принесите Зардету Черному Когтю слезу Тиллоа из Темнолесья и мускусный корень из Болотины.','Лорд Вишлок наделал немалого переполоху среди Благородных домов. Он прознал о наших делах и теперь собирается добиться полного расследования. У меня есть план, согласно которому можно занять Вишлока другим делом, но понадобится твоя помощь.$b$bЕсть один цветочек под названием "слеза Тиллоа", он растет в садах Сталвана поблизости от Темнолесья. Еще мне понадобится мускусный корень, который можно найти только у подножия Каменной дамбы в Болотине.','','','','','',''),
(343,'Кстати, о стойкости духа','Отправляйтесь в Королевскую библиотеку Крепости Штормграда и поговорите с Милтоном Снопом. Он даст вам книгу по металлургии, которая интересует брата Кристофа.','Я готовлю важную лекцию по стойкости духа и хотел бы освежить в памяти несколько мест из важной работы в области металлургии, "Как закалялось железо". Копия этой книги должна быть в Королевской библиотеке Крепости Штормграда. Не могли бы вы заказать ее для меня? Да осенит вас благодать Света!$B$BКоролевская библиотека очень велика, но старший библиотекарь, Милтон Сноп, знает каталог как свои пять пальцев. Поговорите с ним, он принесет для вас книгу.','','','','','',''),
(344,'Брат Пакстон','Поговорите с братом Пакстоном из Аббатства Североземья.','"Как закалялось железо"? Конечно, я знаю такую книгу. Отличная книга, лет двадцать назад написанная дворфом-горняком Маргульфом Благгоном. Он много времени провел в горах Каз Модана, добывая руду. Отличный парень!$B$BНо о чем это я? Ах, да... "Как закалялось железо"! Боюсь, что книга отправилась в Аббатство Североземья. Хранитель тамошней библиотеки, брат Пакстон, хотел сделать с нее копию для своей коллекции.$B$BУж сколько тому месяцев минуло... Интересно, почему он ее задерживает.','','','','','',''),
(347,'Ретбанская руда','Добудьте 5 кусков ретбанской руды и принесите их брату Пакстону в библиотеку Североземского аббатства.','Ретбанская руда получила свое название по имени первооткрывателя, Барта Ретбана. Выплавленный металл мягче железа, но руда имеет приятный темный цвет, и многие переписчики используют ее для изготовления чернил. Добыть руду можно в пещерах Ретбана к северу отсюда.$B$BК сожалению, постоянные нападения орков отвлекают нас от добычи руды, и запасы наши иссякли. Скажу тебе еще вот что... Красногорские гноллы недавно поселились в пещерах Ретбана, и их работяги как раз добывают там руду.$B$BТак что если тебе нужна руда... ты знаешь, как добыть ее.','','','','','',''),
(353,'Посылка для Грозовой Вершины','Доставьте посылку горному пехотинцу Грозовой Вершине в Лок Модан.','Грозовая Вершина – уважаемый клан дворфов, известный своими изысканными и утонченными вкусами. Неудивительно, что Грингер Грозовая Вершина, горный пехотинец Стальгорна, обратился ко мне, когда ему понадобилось оружие.$B$BЗаказ выполнен, но Грингер служит далеко отсюда, в Лок Модане. Если вы собираетесь на север, не возьметесь ли доставить груз?$b$BПо моим последним данным, горный пехотинец Грозовая Вершина остановился в северной сторожевой башне в Лок Модане.','','','','','',''),
(377,'Преступление и наказание','Принесите советнику Миллстайпу руку Декстрена Варда.','Мало того, что столица бросила Темнолесье на произвол судьбы, теперь Благородные дома плюнули на решение городского совета Темнолесья и заточили Декстрена Варда в тюрьму Штормграда – вместо того, чтобы обезглавить злодея по приказу лорда Чернодрева.$b$bВард продавал тела с кладбища Морбенту Скверну. Подобное преступление карается смертью. И все же Штормград объявил Варда своим пленником.$b$bУбей Варда в тюрьме Штормграда, принеси мне его руку, и я тебя вознагражу.','','','','','',''),
(386,'Что происходит?','Принесите голову Таргорра Ужасного стражнику Бертону в Приозерье.','Таргорр Ужасный служил под началом Гат''Илзогга старшим палачом и даже среди жестоких орков отличался особой кровожадностью. По его прихоти отважных бойцов Королевства подвергали страшным пыткам. Его взяли в плен и поместили в тюрьму Штормграда, приговорив к смертной казни. Но происходит что-то странное. Один из знатных людей запретил его казнить. Уверен, дело нечисто.$b$bПоложи конец Таргорру Ужасному, $n. Отправляйся в тюрьму и обезглавь его, пока мы не пали жертвой предательства.','','','','','',''),
(387,'Подавление бунта','Тюремщик Телвотер просит вас убить в тюрьме 10 узников из Братства Справедливости, 8 каторжников из Братства Справедливости и 8 мятежников из Братства Справедливости.','Бунт должен быть подавлен! И ты мне в этом поможешь. Если станет известно, что в тюрьме случился бунт, я потеряю работу. Это исключительная подлость! Самое важное сейчас – немедленно взять тюрьму под контроль. Ради безопасности Штормграда.$b$bНаказание за бунт в тюрьме – смертная казнь. Убей несколько этих отщепенцев, это даст урок всем остальным, и ситуация войдет в норму.','','','','','',''),
(388,'Цвет крови','Принесите Никове Раскол 10 красных шерстяных бандан.','Кровь моя стынет в жилах от ужасного горя... Мой внук Мак… он был такой чудесный мальчик. Всего 14 лет. Когда армия ушла на фронт, он счел, что должен защитить город. Он был охранником в тюрьмe, куда прибыла партия заключенных из Братства Справедливости. Мак наказал некоторых заключенных за порчу шерстяного одеяла, из которого они изготовили головные повязки, знаки их банды. За это он получил нож в спину.$b$bЯ хочу мести. Принесите мне 10 этих проклятых шерстяных бандан. Они цвета крови...','','','','','',''),
(389,'Базиль Тредд','Поговорите с надзирателем Телвотером в тюрьме.','ван Клиф и я были членами гильдии каменщиков. Это мы восстанавливали Штормград после войны.$B$BКогда мы закончили работу, вельможи отказались платить нам за нее. Руководителям гильдии предложили места на государственной службе, но ван Клиф отказался, потому что превыше всего ценил интересы гильдии. Он поднял мятеж и покинул город, поклявшись отомстить.$b$bЕго лейтенант, Базиль Тредд, много знает о планах своего командира. Базиль содержится в плену в тюрьме.','','','','','',''),
(391,'Бунтовщики в тюрьме','Убейте Базиля Тредда и принесите его голову Телвотеру в тюрьму Штормграда.','Скажу тебе сразу, $n: я тебе ни капли не доверяю. Но в нынешней ситуации это не особо важно.$B$BЧто от тебя требуется: иди и поговори с Треддом. Если ты и вправду на нашей стороне, убей его и принеси мне его голову. А если ты на их стороне и не вернешься вовремя, то будешь долго, долго гнить заживо…','','','','','',''),
(399,'Скромные дары прошлого','Обыщите дом Бароса Алекстона в Западном Крае, найдите компас и вернитесь на Соборную площадь Штормграда.','С тех пор как я мальчишкой работал на ферме в Западном Крае, прошла целая вечность. Говорят, нельзя вернуться в прошлое – и это верно. Дважды верно, если говорить обо мне – ведь мой родной дом был разграблен ворами и сожжен.$b$bЯ спросил у отца о судьбе некоторых моих вещей, например, о моем первом компасе. Отец не мог его захватить при бегстве, но сказал, что компас спрятан где-то на ферме.$b$bУсадьба Алекстона расположена к западу от Сторожевого холма. Может быть, ты найдешь мой компас?','','','','','',''),
(454,'После засады','Поговорите с Мираном.','До этого... случая мы все время таскали туда-сюда бочки с порохом. Теперь придется поделить работу: Миран понесет часть бочек, а я присмотрю за остальными.$b$bМне не хочется отпускать Мирана одного. Когда он соберется в путь, проводи, пожалуйста, его.','','','','','',''),
(455,'Альгазская битва','Пройдите через Дун Альгаз.$B$BУбейте 8 разведчиков из клана Драконьей Пасти и 6 рубак из клана Драконьей Пасти.$B$BОб исполнении доложите Валстагу Сталезубу в Гавани Менетилов.','Орки из клана Драконьей Пасти бесчинствуют по всей Болотине. А сейчас они двинулись на Дун Альгаз! Нельзя допустить, чтобы они здесь закрепились, иначе Лок Модан будет отрезан от Гавани Менетилов, нашего порта и крепости в Болотине.$B$BПопытайся прорваться сквозь Дун Альгаз в Болотине и убей столько орков, сколько сумеешь! Чем больше, тем лучше! Об исполнении доложишь Валстагу Сталезубу в Гавани Менетилов.$B$BНайти Менетилов несложно: пройдешь через Дун Альгаз, потом – по дороге на север, а на развилке свернешь на запад.$B$BМы очень надеемся на тебя, $n. Не подведи нас.','Проникнуть в Дун Альгаз.','','','','',''),
(463,'Страж Природы','Найдите Зеленого Стража.','Ты ведь $gслышал:слышала; рассказы о Зеленом Страже? Я даже подозреваю, что ты и разыскать его хочешь. Если так, то скажу тебе, что это чистое безумие! Впрочем, не мне тебя отговаривать: хочешь найти верную смерть – пожалуйста, милости просим.$B$BОн живет на болотах, к востоку от развилки на дороге, ведущей в Дун Модр. Рыщет там на пару с кроколисками... и прочими тварями.$B$BОставь-ка свои денежки мне – покойникам они все равно не нужны. Да и Зеленый Дядя может обломать зуб о твои золотые, когда будет перекусывать тебя надвое... Ты ведь не хочешь, чтобы бедняга потом мучился?','','','','','',''),
(464,'Боевые знамена','Принесите 8 боевых знамен клана Драконьей Пасти капитану Крепкому Кулаку.','К концу Второй войны клан орков Драконьей Пасти потерял власть над красными драконами и был почти уничтожен. Драконы припомнили им все, гнали бывших хозяев аж до самого Грим Батола. Затем орки скрылись в горах к востоку от раскопа Вельгара.$B$BОтсидевшись в горах, они вновь набрали силу и теперь разбили лагерь к северо-востоку от Менетила.$B$BНапади на этот лагерь, посей панику в рядах орков. В доказательство содеянного принеси мне боевые знамена клана.','','','','','',''),
(466,'Поиски огневита','Принесите 6 партий огневитовой руды пилоту Камнекожицу в Дун Морог.','Я слышал о редком виде руды – огневите. Его добывают в Болотине, в пещере к северо-западу от Врат Альгаза. Огневит очень неустойчив – чуть что, сразу взрывается. Однако я уверен, что если правильно его выплавить, то можно делать из него мощнейшие снаряды для пушек!$B$BРаздобудь для меня огневитовую руду, а я пока поищу добровольца, который согласится принять участие в опытах.$B$BАх да, чтобы добыть руду, тебе нужны познания в горном деле. Если у тебя нет необходимых знаний, то... отправь в шахту кого-нибудь из знакомых рудокопов!','','','','','',''),
(467,'Найдите Камнекожца','Поговорите с пилотом Камнекожицем.','Пилот Камнекожиц любит свою осадную машину, как и все пилоты осадных машин! И он всегда рад найти новый способ повысить огневую мощь своих орудий.$B$BДо него дошли слухи о редкой руде, и он ищет кого-нибудь, кто добудет ее. И если тебе уже не терпится взяться за это дело, то найди Камнекожица в поселке Сталежара в Дун Мороге и спроси, чего он хочет.','','','','','',''),
(468,'Отчитайтесь перед горным пехотинцем Рокхаром.','Поговорите с горным пехотинцем Рокхаром.','Горный пехотинец Рокхар ищет добровольцев для похода через Дун Альгаз в Болотину!$B$BЕсли желаете омыть сапоги в болотной жиже и снискать приключений на свою голову – поговорите со Скальным Панцирником в Дун Альгаз. Это к северу отсюда, по дороге за сторожевой башней.','','','','','',''),
(470,'Прожорливый слизнюк','Отнимите сумку Сиды у неизвестного слизнюка возле гробницы Железноборода и верните ее хозяйке в Гавань Менетилов.','Каждую неделю я хожу к Гробнице Железноборода, и в этот раз все было как всегда, но вдруг на меня напали омерзительные хлюпающие слизнюки! Я так растерялась...$b$bЯ бросила в одного из них сумку, но он взял и засосал ее! Мне едва хватило времени, чтобы сбежать.$b$bА в сумке-то мои вещи!$b$bЯ даже не знаю, какой из этих гадов ее сожрал – они все одинаковые! Гробница Железноборода находится к северо-востоку отсюда, возле Дун Модра. Спасибо, что $Gсогласился:согласилась; помочь!','','','','','',''),
(471,'Тяжкая судьба помощника','Принесите 6 шкур гигантских кроколисков Джеймсу Халлорану в Гавань Менетилов.','Недавно я отправил помощника на болото за шкурами гигантских болотных кроколисков. Он не вернулся обратно, и я отправился на поиски... Скажем так: зрелище было не для слабонервных.$b$bЛекарь говорит, что мальчик выживет, и слава богу, но у меня-то работа стоит!$b$bЕсли у тебя есть желание поохотиться на кроколисков, я препятствовать не стану – особенно после того, что они сделали с моим помощником. Кроколиски водятся на побережье к северу отсюда, за поселением мурлоков.','','','','','',''),
(472,'Падение Дун Модра','Отыщите Грима Длинную Косу возле Дун Модра.','Дворфы Черного Железа захватили Дун Модр!$b$bЯ тяжело ранен, |3-6($c). Почти все мои однополчане погибли! Подонки из клана Черного Железа набросились на нас, не успели мы оправиться после взрыва.$b$bНаш командир, Длинная Коса, протрубил сигнал к отступлению. Во время бегства мне в спину попал топорик. Я потерял сознание...$b$bОчнулся уже в Менетиле, но меня волнует судьба остальных солдат. Надежда умирает последней... Может быть, Длинная Коса тоже спасся! Иди в Дун Модр и отыщи его, $r!','','','','','',''),
(484,'Шкуры молодых кроколисков','Принесите $1oa |4шкуру:шкуры:шкур; молодых кроколисков Джеймсу Халлорану в Гавань Менетилов.','Ты, наверное, $gслышал:слышала; обо мне. Я Джеймс Халлоран, кожевник. Выделанные мною кроколисковые шкуры расходятся по всему миру!$b$bУже $gвстречался:встречалась; с Эйнаром? Он – один из охотников, приносящих мне шкуры.$b$bВ последнее время у меня осталось мало мягких шкур, а их можно снять только с молодых кроколисков.$b$bУчитывая обстоятельства, я готов заплатить высокую цену за стопку шкур. Молодые кроколиски обитают в водах прямо за городом.','','','','','',''),
(538,'Южнобережье','Поговорите с Хранителем мудрости Диббсом в Южнобережье.','Доброго дня вам, $n. Если вы не против долгого путешествия, то у меня для вас найдется задание, которое поможет пополнить библиотеку Штормграда.$B$BВместе со старым королевством Альтерака во время войны погибла и огромнейшая библиотека. Жаль, что город разрушен, но вдвойне жаль, что пропал бесценный кладезь знаний! Мы должны восстановить все, что можем.$B$BЮжнобережье – ближайший к руинам Альтерака город. Отправляйтесь туда и поговорите с Хранителем мудрости Диббсом. Он направит вас к руинам, может быть, там вы сумеете найти книги...','','','','','',''),
(631,'Мост Тандола','Найдите Ржавого Засова.','Я помню, как горы содрогнулись от ужаснейшего взрыва. Неслабо рвануло, скажу я тебе!$b$bНа мосту Тандола погибли лучшие из наших солдат. Длинная Коса говорит, что дворфы Черного Железа еще заплатят нам за все до конца этой войны.$b$bНо сейчас у нас отчаянное положение, подкрепления все нет и нет. Длинная Коса отправил Ржавого Засова на разведку к восточному мосту – посмотреть, можно ли защитить мост теми силами, которые сейчас у нас есть.$b$bПрошло уже несколько дней. Мы не можем отправить солдат на поиски – Дун Модр осажден...$b$bБыть может, ты согласишься поискать нашего разведчика?','','','','','',''),
(729,'Рассеянный геолог','Отправляйтесь на юг, найдите геолога Сомнамбулера и узнайте, как у него дела.','Мне была оказана большая честь, когда мастер Седоус назначил меня работать под руководством великого геолога Сомнамбулера. В академии в Стальгорне все знают о грандиозных открытиях Сомнамбулера.$b$bНо геолог довольно... ммм... рассеян... порой кажется, что он не от мира сего.$b$bМы обнаружили признаки некогда крупного поселения. Из-под земли выскочили ужасные големы и заполонили весь раскоп. Но Сомнамбулер, казалось, так ничего и не заметил. Я побежала обратно в Аубердин за помощью.$b$bПрошу тебя, отправляйся на юг и посмотри, все ли в порядке с геологом!','','','','','',''),
(894,'Самофланж','Получите доступ к терминалу в исследовательском центре Торговой Компании.','Торговая Компания устроила к северу отсюда, в юго-западной части Нефтяного болота, небольшой исследовательский центр. Я не очень хорошо представляю, чем они занимаются, но до меня дошли сведения, что они проводят эксперименты со штукой под названием "самофланж".$B$BЧто еще за самофланж? Как бы то ни было, я хочу исследовать его, а значит, мне надо его заполучить.$B$BМне удалось достать копию их руководства пользователя. Почитай его, там наверняка написано, как вытащить самофланж из терминала.','','','','','',''),
(896,'Удача шахтера','Заберите изумруд "Кошачий глаз" у одного из надзирателей или головорезов Торговой компании и отдайте его управляющему пристанью Головокружилкинсу в Кабестане.','Хозяин причала в таком оживленном порту, как Кабестан, держит руку на пульсе происходящего. Я в курсе всего товарообмена между нашим городом и Пиратской бухтой.$B$BПоследние слухи касаются Каменного карьера, принадлежащего Торговой Компании, что на северо-востоке от Нефтяного болота. Один из шахтеров нашел изумруд размером с твой кулак. Я знаю несколько покупателей на такой товар и готов поделиться с тобой комиссией.','','','','','',''),
(914,'Повелители Змей','Принесите камни Кобрана, Анакондры, Пифаса и Серпентиса Наре Буйногривой, на Громовой Утес.','Друиды в Пещерах Стенаний, Друиды Клыка поражены порчей. Когда-то они были частью ордена друидов давшего обет исцелить Степи, но теперь они хотят перекроить эти земли в соответствии со своими извращенными мечтаниями.$B$BУ Друидов Клыка четыре предводителя и каждый обладает Камнем Сновидения. Даже теперь их лица преследуют меня в кошмарах. Убей предводителей друидов, принеси мне их камни и в Степях снова воцарится мир.$B$BИди, $n,  и разыщи их укрытия в Пещерах Стенаний.','','','','','',''),
(942,'Рассеянный геолог','Отвезите таинственную окаменелость археологу Бутылопузу в Гавань Менетилов.','Эта окаменелость поразительно похожа на другую, которую я однажды видел в Стальгорне. Геолог по имени Бутылопуз приносил ее на ежегодную конференцию Лиги Исследователей. Он был уверен, что в этой окаменелости скрыта мощь, которую можно каким-то образом высвободить.$b$bПоследнее, что я слышал, что Бутылопуз обосновался в таверне "Большая вода" и ждет, чтобы его сопроводили к раскопу Вельгара. Найдите его и покажите ему окаменелость, найденную Сомнамбулером. Может быть, он сумеет раскрыть секреты прошлого.$b$bКорабль в Менетилов отходит из Аубердина.','','','','','',''),
(943,'Рассеянный геолог','Археолог Бутылопуз в Гавани Менетилов хочет, чтобы вы принесли ему камень Релу и окаменелость Бутылопуза.','Геолог Вельгар, который сейчас находится на раскопе в Болотине, держит окаменелость у себя. Когда я обнаружил камень Релу, то был уверен, что это ключ к тайне окаменелости.$b$bПока я шел по дороге к Вельгару, на меня напали ящеры, и реликвия пропала. Не знаю, какая из крапчатых тварей проглотила ее, но если вам удастся ее вернуть, я смогу высвободить силу этих артефактов.$b$bПринесите мне и камень Релу, и окаменелость, хранящуюся у Вельгара.','','','','','',''),
(947,'Грибы из пещеры','Принесите 5 ножек струпника и 1 мертвянку Баритасу Лунному Сумраку в Аубердин.','Я тут составляю одно зелье, для которого нужны редкие грибы, растущие в одной-единственной пещере. Пещера эта находится за водопадом Скалистый, к востоку и чуть севернее в горах.$b$bЯ бы и сам туда пошел, но в Роще Древних мне порекомендовали держаться подальше от того места. Наши почтенные союзники чувствуют, что в этой пещере таится какое-то незнакомое зло.$b$bПрошу вас, $n, соберите для меня эти грибы. А в процессе заодно приглядитесь: может быть, вы сможете подтвердить опасения Дерев.','','','','','',''),
(948,'Ону','Поговорите с Ону в Роще Древних.','Ону, Древо Мудрости из Рощи Древних, знает о вашем путешествии к Скалистому водопаду и хочет поговорить с вами. Роща расположена к югу отсюда, у подножья гор.$b$bДерева терпеливы и мудры, $n. Но если Ону ищет вашего совета касательно того, что вы видели у водопадов, то, боюсь, дело срочное.','','','','','',''),
(952,'Роща Древних','Доставьте письмо Фэндрала Ону в Рощу Древних на Темные берега к югу от Аубердина.','Если уж у тебя нашлось время передать письмо для Древа-оракула, то, мне кажется, для тебя не составит труда отнести донесение в Рощу Древних на Темный Берег, прямо к югу от Аубердина.$b$bТы наверняка сможешь свободно добраться туда на гиппогрифе, я уверен, что ты сумеешь это сделать. Отнеси это Ону, Древу Мудрости. Он ждет от меня вести, точно так же, как я ждал вести с Поляны Оракула.','','','','','',''),
(959,'Неприятности в порту','Оператор крана Биггльфузз из Кабестана попросил вас отнять бутылку портвейна 99-летней выдержки у Безумного Магглиша, который прячется в Пещерах Стенаний.','Ой! $b$bКак видишь, у меня сегодня приключилась неприятность! Утром из Пиратской бухты пришла поставка. И какая! Никогда не видел столько ящиков. Я хотел побыстрее закончить, поэтому поднимал больше, чем следовало. В конце концов все рухнуло на землю.$B$BНе успел я оглянуться, как эта тварь, Безумный Магглиш, схватил бутылку портвейна 99-летней выдержки и бросился наутек. Я гнался за ним до самых Пещер Стенаний, но внутрь я не ходок.$B$BМожет, тебе хватит пороху, чтобы найти его?','','','','','',''),
(962,'Змеецвет','Аптекарша Зама из Громового Утеса просит вас принести ей 10 змеецветов.','Королевское фармацевтическое общество из великого Подгорода Лордерона направило меня сюда с очень необычной целью, $n. Возможно, вы сумеете помочь мне, а, стало быть, и Темной Госпоже в трудах на благо Отрекшихся.$b$bНе так давно я изучала редкий образец флоры под названием змеецвет. Я уверена, что в большом количестве это растение таит в себе великие возможности.$b$bУвы, змеецвет можно найти только в самых темных закоулках Пещер Стенаний, опасной системе подземелий в Степях.','','','','','',''),
(963,'Во имя вечной любви','Освободите дух Анайи Вестницы Рассвета и принесите ее подвеску Кириллиану Белому Когтю в Аубердин.','После битв за Источник Вечности я узнал, что Амет''Аран разрушен, жители его погибли – в том числе и моя возлюбленная Анайя.$b$bЯ никогда не думал, что и через тысячи лет воспоминания об Анайе будут тревожить мои сны. Бродя в помрачении рассудка по лесам на Темном Берегу, я очутился в руинах Амет''Арана... где и увидел неупокоенный дух моей любимой.$b$bЕе нужно освободить, но у меня просто рука не поднимается. Нужно уничтожить ее призрак.','','','','','',''),
(965,'Башня Алталакса','Найдите Балтула Удар Тени возле башни Алталакса на Темном Берегу.','Привет тебе, $gюный:юная:r; |3-6($r). Меня зовут Элисса Звездный Ветер, и моя задача – защищать Аубердин от всякого вреда.$b$bС этой целью я послала Балтула Удар Тени вести наблюдение за странными событиями, происходящими близ башни Алталакса к северо-востоку отсюда.$b$bНо он уже давно должен был вернуться. Боюсь, что он столкнулся в лесу с какой-то непредвиденной опасностью. Я была бы тебе очень благодарна, если бы ты $gсмог:смогла; найти его и удостовериться, что с ним все в порядке.','','','','','',''),
(967,'Башня Алталакса','Доставьте письмо Балтула Делгрену Очистителю в Ясеневый лес.','Мой хозяин, Делгрен Очиститель – паладин, любезно предоставивший свою помощь в защите наших лесов от сил демонов и нежити. Он многое поведал мне о Божественном Свете и воинском искусстве.$b$bДелгрен должен немедленно узнать о деятельности клана.$b$bВы найдете его далеко на юге отсюда, на Заставе Мейстры в Ясеневом лесу. Поторопитесь – я боюсь, что угроза клана Темной Нити растет с каждым часом.','','','','','',''),
(970,'Башня Алталакса','Добудьте светящийся самоцвет Души и вернитесь к Делгрену Очистителю на заставу Мейстры.','Письмо Балтула приводит меня в ужас. Этот клан Темной Нити – сущее бельмо у меня на глазу, и его надо устранить! Мне приходилось иметь дело с мерзавцами из Темной Нити к северо-востоку отсюда в Ордиль-Аране. У одного из них есть самоцвет Души, в котором, как я думаю, заключается секрет силы клана.$b$bПринеси его мне, а уж я сумею разгадать его тайну.','','','','','',''),
(971,'Знание в пучине','Принесите манускрипт Лоргалиса Геррику Костохвату в Заброшенный грот в Стальгорне.','Насколько вам известно, я собираю знания. Древние знания. Могучие знания. Знания, что отворяют пути, знания, что могут пробудить Тех-Что-Спят.$B$BХодят слухи о старинном манускрипте Лоргалиса, будто бы он покоится в Непроглядной Пучине Ясеневого леса. Некогда там жили эльфы, но они давно уже мертвы. Эльфы эти обладали великим знанием, до того как их город превратился в руины.$B$BНайдите манускрипт в Непроглядной Пучине Сделайте это, и я не забуду вашей услуги. Даже после... скончания дней.','','','','','',''),
(982,'Безбрежное море, глубокий океан','Добудьте денежный ящик "Серебряной Зари" и денежный ящик "Туманной Пелены" для Горбольда Стальная Рука в Аубердине. Оба предмета можно найти в останках потерпевших крушение кораблей к северу от деревни.','У побережья Темного Берега, к северу от нас, есть остатки двух потерпевших крушение кораблей – "Серебряной Зари" и "Туманной Пелены". Некоторое время назад моряки обоих кораблей не поладили с отвратительными мурлоками, когда плыли по безбрежному морю в сторону Аубердина. Теперь корабли лежат на дне океана, став добычей мурлоков$B$BОба капитана погибли в ту ночь, и их судовые журналы и ценные вещи по-прежнему лежат там, в денежных ящиках. Я хотел бы, чтобы ты $gдобыл:добыла; их для нас; это много значило бы для членов команды.','','','','','',''),
(983,'Жужжалка 827','Добудьте 6 ножек крабов и поместите их в Жужжалку 827.','Слушай! Помоги мне с моим последним изобретением, Жужжалкой. С ее помощью можно общаться на расстоянии!$b$bМожет быть, ты уже видел их – такие ящики с рычагами. С ними одна проблема – за ними нужен постоянный уход.$b$bУ каждой из них есть своя проблема, но я нашел хитрое решение. Я поместил все машины в районе обитания существ, части которых нужны для починки каждой конкретной машины. Сейчас неисправна Жужжалка 827. Она находится чуть южнее Аубердина, совсем рядом с ним. Чтобы ее починить, нужно 6 ножек краба. Я заплачу...','','','','','',''),
(990,'Путь в Ясеневый лес','Найдите в Ясеневом лесу Раэну Волкопас.','$n, моя госпожа – Раэна Волкопас – ожидает тебя в городе Астранаар, что в Ясеневом лесу. Возможно, с твоей помощью мы сможем хотя бы немного ослабить порчу, пустившую здесь корни.$B$BОтправляйся отсюда на юг и держись дороги – ты легко найдешь путь, если будешь держаться этого направления.','','','','','',''),
(1010,'Батранов волос','Принесите 5 стеблей Батранова волоса Орендилу Широколисту в Ясеневый лес.','Есть одна травка, что росла некогда в древних руинах Убежища Батрана на севере. Звалась эта травка Батранов волос и славилась тем, что лечила болезни души.$B$BВ этой деревне болеет ребенок, и сдается мне, что это болезнь не телесная. Не сходишь ли ты в Убежище Батрана и не поищешь ли Батранов волос? Мне он может понадобиться, чтобы вылечить ребенка.$B$BУбежище Батрана лежит к северу от заставы Мейстры и прямо к югу от границы с Темным Берегом.','','','','','',''),
(1017,'Маг-призыватель','Убейте Сарилуса Грязнорожденного и принесите его голову часовому Велене Звездный Всполох в Приют Серебряного Ветра.','Есть только один маг из нежити в Степях, способный наслать порчу на стольких элементалей воды. И он единственный, кому хватит дури попытаться это сделать. Сарилус Грязнорожденный, наверное, сидит на вершине Вершины Багрового Тумана, да смеется надо мной. $B$B$n, тебе придется проникнуть на вражескую территорию и уничтожить этого мерзавца. Мне надоела его бестолковость, и надо показать ему, что бывает с теми, кто донимает часовых. $B$BУничтожь его и принеси мне его голову. Но соблюдай осторожность, Орда может подкараулить тебя.','','','','','',''),
(1057,'Возвращение Обугленной долины','Хранитель Албагорм с Пика Каменного Когтя просит вас убить 6 гарпий, 6 душительниц, 6 душегубок и 6 бродяжниц из стаи Кровавой Ярости.','Несомненно, будучи защитником лесных духов, можешь догадаться, почему я так встревожен.$b$bЧтобы достигнуть этого пика, тебе пришлось пройти через горы, и, конечно же, от глаз твоих не ускользнуло искажение, постигшее эту землю. Алчность привела к уничтожению священных холмов.$b$bОбугленная долина на юге сожжена механической армией жадных промышленников. Хуже того, клан Смертельной Ярости, вторгшийся на эти земли, отказывается пропустить нас – а ведь мы могли бы начать восстановление тех краев!$b$bИзгони прочь злобных гарпий, $n!','','','','','',''),
(1069,'Яйца мохового паука','Принесите Мебоку Миззриксу из Кабестана 15 яиц мохового паука.','В Пиратской бухте фантастический спрос на омлеты из паучьих яиц! Проблема в том... что яиц в Бухте нет.$B$BЯ чую прибыль!$B$BНа Утесе Ветрорезов и в Сиширском каньоне, в Когтистых горах на северо-западе, живут моховые пауки. Принеси мне их яйца, и я неплохо заплачу!$B$BНа Утесе Ветрорезов паучьи кладки можно найти под оставшимися деревьями.$B$BВ Сиширском каньоне... хм, если у тебя слабый желудок, можешь собирать яйца только на Утесе Ветрорезов...','','','','','',''),
(1078,'Поиск для Маурена','Принесите 8 кристаллических чешуй Коллину Маурену в Штормград.','Путешественники постоянно спрашивают меня о Когтистых горах. Похоже, все ищут там приключений, причем самых разных: кому-то нужны виверны, кому-то – элементали, а у кого-то дела с Торговой компанией.$B$BВ Обугленной долине, прячущейся среди пиков Когтистых гор, некогда обитали особые виды василисков: их чешуя, размолотая в порошок, была прекрасным реактивом для некоторых заклинаний, созданных мною. $B$BЕсли эти василиски еще живут там, мне надо заполучить хотя бы несколько чешуек.$B$BЕсли не очень торопишься, удели на это немного времени, я хорошо заплачу тебе.','','','','','',''),
(1085,'На страже в Когтистых горах','Поговорите с Гаксимом.','Положение здесь, в Каменном Когте, явно не способствует совместной работе ночного эльфа и гнома.$B$BТорговая компания опустошила эти земли, и большая часть моего времени уходит на то, чтобы положить предел уничтожению.$B$BНе суди Гаксима преждевременно; он понимает, что нам с ним необходимо трудиться вместе.$B$BЕсли ты хочешь помочь нам, то для начала поговори с Гаксимом.$B$BИзвини, что пока не могу отослать тебя обратно к Таре с хорошими новостямиI. Может быть, вскоре...','','','','','',''),
(1093,'Супер-дровосек 6000','Добудьте чертежи "Супер-дровосека 6000" для Зиза Физзикса с Когтистых гор.','Ну, Торговая Компания и наломала дров! О чем они только думали? Гоблинская компания нанимает гнома!$b$bК счастью для меня, Пароклапан всегда может узнать гения с первого взгляда. Он нанял меня сразу же, как меня выгнали оттуда!$b$bМне сказали, что компания строит какие-то огромные лесорубные машины, и Клапан хочет, чтобы я украл для него чертежи. К несчастью, Геренцо – вот ведь злобный гном! – хочет меня убить... может быть, ты вместо меня украдешь чертежи? Они должны быть у кого-то из операторов компании.','','','','','',''),
(1133,'Путешествие в Астранаар','Поговорите с Шиндрелл Огненный Всполох в Астранааре.','Если вы только что прибыли по морю из Менетила, отправляйтесь прямиком в Астранаар. Уверен, такому преданному члену Альянса будет, чем заняться в городе. Поговорите там с Шиндрелл Огненный Всполох и предложите ей свои услуги.$B$BНе стоит говорить ей, кто вас прислал. Шиндрелл меня не знает...','','','','','',''),
(1138,'Дары моря','Соберите 6 кусочков отличного крабьего мяса для Груббера Блумпа в Аубердине.','Мне нравятся крабы. Крабы – это деликатесные дары моря! Их можно печь, жарить на гриле, варить, делать из них бульон. Еще их можно жарить на сковороде, во фритюре и просто жарить. Есть крабовый салат, крабовый суп, краб тушеный, краб перченый, краб лимонный, краб с кнутокорнем, а также стальгорнский крабовый десерт. Вот и... ну, и все.$b$bЯ здесь сейчас рыбу ужу, потому охотиться на сочных крабов мне некогда. Можешь извлечь кусочки отличного мяса из рифовых крабов и покрытых илом крабов. Их можно печь, жарить на гриле, варить...','','','','','',''),
(1140,'Башня Алталакса','Освободите заточенные души высокорожденных на Ночной поляне и Сатирнааре, затем вернитесь к Делгрену Очистителю на заставу Мейстры.','Орочьи письмена немногим лучше детских каракулей. Многие из моих собратьев по ордену кривились, когда я решил изучать их язык, но мне это сильно помогает понимать врагов. $b$bИз каракулей Илкруда можно понять, что у Атрикуса еще оставались два самоцвета души, и они хранились на Ночной поляне и Сатирнааре, занятых сатирами местах на северо-востоке Ясеневого леса.$b$bПоосторожнее там, $n, от вида кровавых храмов сатиров содрогнется даже $Gтакой закаленный:такая закаленная:c; |3-6($c), как ты.','','','','','',''),
(1198,'В поисках Талрида','Найдите стража Талрида из ордена Серебряного Рассвета в Непроглядной Пучине.','В нынешние дни много слухов ходит о союзе Сумеречного Молота и наг в Непроглядной Пучине на побережье Ясеневого леса.$b$bЯ должен собрать как можно больше сведений для Серебряного Рассвета, что бы мы могли понять, где и когда нужна наша помощь.$b$bУже много недель прошло, как я отправил разведчика выяснить, что происходит в Непроглядной Пучине. Страж Талрид из ордена Серебряного Рассвета до сих пор не вернулся.$b$bДругие мои разведчики заняты насущными делами.$b$bПомоги мне найти Талрида, $n.','','','','','',''),
(1199,'Наступление сумерек','Принесите 10 подвесок сумерек стражу Менадосу из ордена Серебряного Рассвета в Дарнасс.','Черпая силу из старинных обрядов, посвященных Древним Богам Хаоса, Сумеречный Молот пытается вернуть своих темных покровителей и распространить смерть и ужас по всему миру.$b$bМы думаем, что Сумеречный Молот в союзе с нагами, и теперь они накапливают силы в Непроглядной Пучине на побережье Ясеневого леса.$b$bЧто бы ни затевалось в глубинах древнего храма, этим планам нельзя дать осуществиться.$b$bОбъяви же войну Молоту и вернись с доказательствами своих подвигов! Твои труды будут достойно вознаграждены.','','','','','',''),
(1221,'Корни Синелиста','Возьмите ящик с дырками.$BВозьмите палочку-погонялочку для шмыгуносов.$BВозьмите справочник по шмыгуносам. $B$BВ Лабиринтах Иглошкурых выпустите шмыгуноса и воспользуйтесь стеком, чтобы он начал искать корни. $B$BПринесите 6 корней синелиста, стек и ящик с дырками Мебоку Миззриксу в Кабестан.','Корень синелиста – признанный деликатес в любом уголке мира! Но растет он только здесь, в Пустошах, глубоко под землей в Лабиринтах Иглошкурых.$B$BК тому же клубни так сложно найти, если не знать точно где искать! Поэтому я специально надрессировал этих шмыгуносов, чтобы они находили корни под землей. Обоняние у них просто невероятное – они чуют корни с пятидесяти шагов!$B$BЗадачка, конечно, непростая, но если принесешь мне корней, я хорошо заплачу.','','','','','',''),
(1275,'Исследование порчи','Гершал Шепот Ночи в Аубердине хочет, чтобы вы принесли ему 8 оскверненных стволов мозга.','Безрассудные эльфы крови попали в западню демонической магии. Разве они не видели, что случилось с нагами и сатирами Калимдора?$b$bЯ боюсь, что эльфы крови могут претерпеть такую же трансформацию. Азерот не может позволить себе породить еще одну расу злобных монстров.$B$BЯ хотел бы изучить ствол мозга сатиров и нагов, чтобы понять, на что обрекают себя эльфы крови. И сатиров, и нагов вы найдете в Непроглядной Пучине, на побережье Ясеневого леса.$b$bПуть неблизкий, $n.','','','','','',''),
(1483,'Зиз Физзикс','Поговорите с Зизом Физзиксом на Утесе Ветрорезов.','Торговая Компания переманила лучшие гоблинские умы, но порой у нас появляется возможность вернуть свое. $B$BНекоторое время назад подразделение Торговой Компании в Когтистых горах приняло на работу Геренцо Терминатрикса – гнома! Это так ошарашило другого инженера, Зиза Физзикса, что он умолял меня найти ему новую работу в Союзе ремонтников. Я дал ему несколько заданий, но ему может понадобиться помощь.$B$BНе навестишь его? Он живет у западного края Утеса Ветрорезов.','','','','','',''),
(1486,'Шкуры загадочных существ','Принесите 20 искаженных шкур Налпаку в Пещерах Стенаний.','Пока Наралекс погружался в свои кошмары все глубже, из-под Степей в Пещеры Стенаний пришли какие-то странные животные.$b$bЭти искаженные существа наделены странными, потусторонними силами. В то время как зло в их природе, я уверен, что из их существования можно извлечь некоторую пользу здесь в Калимдоре. Я верю, что из их кожи наши кожевники смастерят что-нибудь стоящее.$b$bЕсли эта задача тебе по вкусу, отправляйся в пещеры и принеси мне немного искаженных шкур.','','','','','',''),
(1487,'Искоренение Скверны','Убейте для Эбру 7 загадочных опустошителей, 7 загадочных гадюк, 7 загадочных шаркунов и 7 загадочных страхозубов.','Цели у Наралекса были самые благие.$b$bНаш лидер стремился впасть в Изумрудный сон, и  вновь превратить эти выжженные земли в тот пышный лес, которым они когда-то являлись. Но что-то пошло не так.$b$bМечта Наралекса превратилась в кошмар, и порченые твари заселили пещеры.$b$bВ то время как некоторые приспешники Наралекса стремятся пробудить нашего мастера, я забочусь о том, чтобы избавить эти пещеры от заполонивших их тварей.$b$bОтправляйся туда, $n. и уничтожь порченое семя.','','','','','',''),
(1491,'Умный напиток','Принесите 6 порций воющей субстанции Мебоку Миззриксу в Кабестан.','Ладно, рога ящеров не подошли. Ничего страшного, с первого раза никому не удается разбогатеть. Кроме того, мне удалось придумать кое-что получше! $B$BСуществует вещество, именуемое воющей субстанцией, и мне кажется, именно из-за него в Степях такие странные растения и животные. Принеси мне немного субстанции, и я попробую добавить ее в напиток!$B$BНасколько я знаю, это вещество накапливается в эктоплазматических существах в Пещерах Стенаний на западе. Убей несколько существ из пещер и собери из них субстанцию.','','','','','',''),
(1667,'Джек Мертвозуб','Добыть знак маршала Хаггарда из лагеря Джека Мертвозуба и вернуться к маршалу Хаггарду.','Тебя ведь прислал Баргард? Да, у меня есть запасное оружие, но сначала я хочу дать тебе задание…$b$bНекоторое время назад меня обманул злодей из Братства Справедливости, Джек Мертвозуб. Он пришел в темноте, одетый в гербовую накидку Штормграда, и я принял его за маршала Дугхана. Джек сказал, что ему нужен мой старый знак маршала, и я, не раздумывая, отдал его... а потом он захохотал и сбежал, прежде, чем я успел его схватить!$b$bВерни мне мой знак! Джек Мертвозуб наверняка прячет его в лагере на юге.','','','','','',''),
(1699,'Ретбанский вызов','Войдите в пещеры Ретбана, доберитесь до первой развилки и вернитесь к Йорусу Ячменовару за отведенное время.$b$bВы не должны умирать и освобождать свой дух.','Я называю мое испытание Ретбанским вызовом. Чтобы пройти его тебе всего-то нужно войти в пещеры Ретбана, дойти до первой развилки и вернуться. Элементарно! Есть, правда, несколько "но"…$b$BВернуться тебе придется в течение часа.$b$bТам полно красногорских гноллов.$b$bПеред тем, как тронуться в путь, тебе придется глотнуть фирменного напитка моей семьи, жгучего пива семейства Ячменевец!$b$bЧто скажешь? Пещеры Ретбана находятся в холмах на севере от Озер. Ты $gготов:готова; принять Ретбанский вызов?','Войдите в пещеры Ретбана','','','','',''),
(1701,'Закаленный доспех','Соберите все необходимые материалы для Фьюрена Длинноборода и отнесите их в Штормград.','Ну вот, я дал тебе отличный щит, но это еще не все. Я знаю секрет изготовления очень прочного доспеха. Это нелегко, и мне потребуются редкие материалы, но если тебе не лень за ними поохотиться, доспех получится несравненный.$b$bЧто скажешь? Если ты не боишься трудностей, я выдам тебе список необходимых материалов и где их искать.','','','','','',''),
(1716,'Пожирательница душ','Поговорите с Такаром Провидцем в Степях.','Сайаады – пожиратели душ, подавляющие волю и вводящие в искушение. Порождение чистого зла.\n\nВ легкомысленных историях этих демонов называют суккубами, если речь о женщинах, и инкубами, если это мужчины.\n\nПримани демона символом любви, победи его – и он будет тебе служить.\n\nНо найти подходящий символ непросто. Поговори с Такаром Провидцем. Ты найдешь его в калимдорских Степях возле лагеря Таурахо.','','','','','',''),
(1738,'Сердцедрево','Раздобудьте в Ясеневом лесу сердцедрево и принесите его Гакину Темнопряду в Квартал магов Штормграда.','Готовясь к твоему приходу, я на скорую руку оглядел весь мир, проник взглядом сквозь пелену времени и нашел то, что тебе нужно.$b$bВо время Войны Древних двое влюбленных вместе пали в битве. Там, где перестали биться их сердца, выросло дерево, известное как сердцедрево – символ их бессмертной любви.$b$bЭтого должно быть достаточно, чтобы привлечь суккуба. Руины Ордиль-Арана, где растет сердцедрево, находятся в северо-западной части Ясеневого леса.','','','','','',''),
(1740,'Шар Соран''рука','Соберите 3 фрагмента Соран''рука и 1 большой фрагмент Соран''рука и принесите их Доану Кархану в Степи.','Когда демоны Легиона попадают в немилость, их души заключают в сферы и раздают магам и чернокнижникам.$B$BМногих из них носили на Азероте их слуги. Даже расколотые на части, эти сферы хранят в себе силу демонов, заключенных внутри. Шар Соран''рука был расколот надвое. Одну из частей раздробили на еще более мелкие фрагменты послушники Сумеречного Молота в Непроглядной Пучине. А другая, большая часть, досталась волшебнику из крепости Темного Клыка. Найди их, и я смогу воссоздать этот шар.','','','','','',''),
(1921,'Сбор материалов','Отнесите 10 кусков льна и 6 заряженных самоцветов Расселины Уинн Ларсон в Штормград.','За верную службу своим собратьям-магам тебе полагается одеяние волшебника. Его вполне может сшить Уинн Ларсон, если ты принесешь ей все необходимое.$b$bСамо одеяние шьется из льна, который легко найти, но кроме него понадобятся заряженные самоцветы Расселины, а их добывают исключительно в Руднике у Серебряного ручейка у озера Лок Модан. Горняки дворфов не смогли забрать их, и они лежат в ящиках по всему руднику.$b$bНабери льна, добудь самоцветы и принеси их Уинн Ларсон в суконную лавку Ларсона в район магов.','','','','','',''),
(2039,'Найти Бинглза','Найдите Бинглза Покрышкинса в Лок Модане.','Мы потеряли связь с Бинглзом! Он был отправлен в разведывательный полет над Гномреганом, и уже неделю от него нет никаких известий. Я знаю только то, что он отправился в разведку и потерпел крушение.$B$BПоследний раз его видели над озером Лок. Возможно, ты сможешь выяснить, что с ним, $n.','','','','','',''),
(2040,'Битва под землей','Принесите Шони Молшунье в Штормград зубчатый спрек-механизм гномов из Мертвых копей.','Гномреган захватили трогги! Ситуация крайне тяжелая, но, быть может, вы cможете помочь, $n.$b$bГлубоко под землей, в Мертвых копях, находится действующий гоблинский резак. Найдите его и принесите его источник питания. С его помощью мы сможем обеспечить наши автогиробуроройки достаточной энергией, чтобы пробиться через каменные границы Гномрегана и открыть дорогу армии гномов!','','','','','',''),
(2041,'Разговор с Шони','Поговорите с Шони Молшуньей в Штормграде.','Возможно... Возможно, вы поможете нам в битве за Гномреган.$B$BВ Штормграде вы найдете командира нашей подземной штурмовой группы, Шони Молшунью. Шони нужна помощь в сооружении автогиробуророек.$B$BВы найдете ее среди дворфов в Штормграде.$B$BУдачи, $n.','','','','','',''),
(2922,'Промыть мозг Техботу','Принесите ядро памяти Техбота мехмастеру Замыкальцу в Стальгорн.','Когда пал наш родной город Гномреган, с Техботом, видимо от расстройства, приключилось короткое замыкание. Бедный мой маленький друг! Он так помогал мне и моим коллегам! В него встроена куча полезных прибамбасов на все случаи жизни, объем памяти просто огромен, но все все это теперь совершенно бесполезно – его мозг из позитронного стал негатронным! Все заложенные в него программы теперь работают наоборот. Мой бедный сумасшедший робот теперь бродит по Гномрегану.$B$BМожет, тебе удастся изловить его и извлечь его ядро памяти. Тогда я смогу разобраться в причинах поломки и, возможно, устраню ее.','','','','','',''),
(2923,'Мехмастер Замыкалец','Поговорите с механомастером Большой Искрой.','Мехмастер Замыкалец крайне опечален судьбой своего творения – Техбота. Помнится, Техбот был когда-то для гномов весьма полезным инструментом, однако теперь Большая Искра говорит, что он сломан.$B$BОчень жаль. Однако, быть может, его еще возможно починить.$B$BПоговори об этом с Мехмастером Замыкальцем в Городе Механиков в Стальгорне. Он будет рад любой помощи.','','','','','',''),
(2924,'Базовый элемент','Принесите 12 базовых элементов Клацморту Гайкокруту в Стальгорн.','Базовый элемент – практически универсальный механизм, широко используемый механиками и кузнецами Гномрегана. Однако в спешке покидая город, никто из нас не догадался прихватить запас этих механизмов с собой. Мне просто необходимо пополнить мои запасы!$B$BПожалуйста, отправляйся в Гномреган и добудь мне побольше таких механизмов. Думаю, их можно найти в подземельях нашего города – обычно они хранятся в контейнерах-экстраполяторах.$B$BУмоляю тебя, поторопись!','','','','','',''),
(2926,'Новая формула','Соберите радиоактивный осадок, оставляемый облученными захватчиками и облученными погромщиками в пустой свинцовый фиал для образцов. Принесите полный фиал Оззи Триггервольту в Каранос.','С самого дня нашего бегства из города Гноарном думает только о том, как выставить троггов из Гномрегана и очистить город от заражения.$B$BУ нас с Раззлом есть некоторые идеи на этот счет, однако похоже, что воплотить их в жизнь сможет только настоящий безумец. Мы еще не знаем, сработает ли наш замысел – надо все как следует проверить! Для этого нам потребуются радиоактивные осадки, оставляемые облученными троггами в Гномрегане. Это зеленая светящаяся субстанция. Наполни ею этот фиал и принеси мне!','','','','','',''),
(2927,'На другой день','Поговорите с Оззи Триггервольтом в Караносе.','Вы ведь не думаете, что я всегда был лысым? Нет, $Gсударь:сударыня;! Эту трагическую утрату волос вызвала утечка радиации в Гномрегане. До тех пор я был единственным кудрявым гномом во всем Азероте.$B$B*Гноарн потрясает в воздухе кулаком.*$B$BБудь прокляты эти проклятые грязные трогги, будь они все прокляты!!!$B$BМожет, еще не поздно, $n. Мы еще можем исправить дело – я хочу сказать, спасти город! Поговорите с Оззи Триггервольтом в Караносе. Они со своим партнером Раззлом как раз пытаются решить эту проблему.','','','','','',''),
(2928,'Сооружение автогиробуророек','Принесите Шони в Штормград 24 горсти механических внутренностей роботов.','Это ужасно, $n. У нас, видно, не хватит запчастей, чтобы собрать всю партию автогиробуророек, которую пора отправить в Дун Морог.$b$bЧто нам точно нужно – так это детали, $n. И для добычи этих деталей не найти места лучше, чем Гномреган! Я слышала, что роботы и механизмы, оставшиеся там, бродят по городу как овцы на вольном пастбище.$b$bЯ хочу от вас, чтобы вы отправились в Гномреган и распотрошили этих роботов на запчасти. Двух дюжин деталей должно хватить.','','','','','',''),
(2929,'Великое предательство','Отправляйтесь в Гномреган и убейте Мекжинера Термоштепселя. Вернитесь к Главному Механику Меггакруту.','Я доверял Термоштепселю, |3-6($r). Никогда я не думал, что он предаст меня и весь гномий род. И ради чего? Ради власти? Богатства? Все это он и так со временем получил бы. Теперь мы лишились родного дома, а этот безумец остался там править. Король пустого места...$B$BМы вернем себе Гномреган, $n. Мы не остановимся, пока город снова не станет нашим! Если ты хочешь присоединиться к нашей борьбе, выполни совсем простое поручение – убей предателя. Уничтожь Мекжинера Термоштепселя.','','','','','',''),
(2930,'Спасение данных','Принесите призматическую перфокарту главному механику Чугунотрубзу в Стальгорн.','Когда мы бежали из Гномрегана, то оставили там столько данных! Жизненно важных данных!$B$BМне нужны данные с призматической перфокарты чрезвычайно секретного терминала матричного перфографа 3005-D, что находится в глубинах Гномрегана. Вам нужно добраться до терминала, но сначала надо получить допуск... а для этого надо добраться до терминалов низшего уровня защиты – моделей -A, -B и -C. А для ЭТОГО вам понадобятся перфокарты допуска, начиная с белой... а все перфокарты остались в городе.$B$BЭто же катастрофа! Вы можете помочь нам?','','','','','',''),
(3370,'Кошмары','Принесите осколок кошмара Матренгилу Медвежьей Лапе в Дарнасс.','Этот осколок сам по себе большая загадка; Это чистая эссенция Изумрудного Сна. Однако, это осколок не сна, а скорее кошмара.$B$BНе хочу тревожить тебя, $n, но лучше будет, отдать его кому-то из старших друидов, как только сможешь.$B$BМатренгил Медвежья Лапа из Круга Кенария, вот кого тебе надо найти. Отправляйся в Дарнасс, точнее сказать не могу.','','','','','',''),
(3765,'Проблема за морем','Отправляйтесь в Аубердин к Гершалу Шепоту Ночи.','Штормград – невероятно суматошный город.$b$bЯ прибыл сюда издалека в поисках помощи. Говорят, отважные искатели приключений нередко бродят по этим улицам.$b$bМой брат Гершала на Темном Берегу нуждается в помощи. Он обитает в приморском городке Аубердине.$b$bЭто путешествие будет долгим и насыщенным. Именно по этой причине я и ищу помощи кого-то, обладающего опытом – такого, как вы, |3-6($c).','','','','','',''),
(4581,'Кайнет Штиль','Отнесите записку Шиндрелл Кайнету Штилю в Лесную Песнь.','Друид Кайнет Штиль прислал мне весточку. Он хотел бы получить отчет обо всем, что творится у нас на побережье и в лесах вокруг Астранаара. Он опасается, что по Ясеневому лесу расползается порча... Может, он и прав.$B$BВот, отнеси ему мой отчет. Ты найдешь его в святилище Лесной Песни, в лесах Ночной Песни к востоку отсюда.','','','','','',''),
(4740,'РАЗЫСКИВАЕТСЯ: Глубомрак!','Найдите и убейте мурлока, известного как Глубомрак. Предполагается, что это существо охраняет и защищает хижины мурлоков в поселении к югу от Аубердина, у воды.$B$BО смерти Глубомрака доложите часовому Глинде Нал''Шии в Аубердине.','Внимание!$B$BНазначена награда за голову мурлока, именуемого "Глубомрак". Эта злобная тварь повинна в смерти как минимум одного часового и подозревается в потоплении как минимум двух грузовых судов в прибрежных водах Темного Берега!$B$BГлубомрака в последний раз видели в поселении мурлоков к югу от Аубердина, и, судя по всему, он охраняет хижины своих сородичей. Награда за голову Глубомрака ждет смельчака у часового Глинды Нал''Шии в Аубердине.$B$BСовет Аубердина','','','','','',''),
(6681,'Поместье, Черный Ворон','Отнесите печать Черного Ворона Фахраду в поместье Черный Ворон, сокрытое среди холмов Хилсбрада.$b$bНе теряйте бдительности. Поиски поместья – проверка на ловкость.','$n,$B$BЧерный Ворон очень заинтересовался тобой, $gюный вор:юная воришка;. Мы наблюдали. Тебе не хватает ловкости, но это преходяще.$b$bЕсли ты хочешь стать $gучеником:ученицей; мастера Черного Ворона и членом Лиги убийц, стоит только принести печать Черного Ворона (приложенную к этому письму) в поместье Черный Ворон.$b$bПервым заданием будет найти его среди холмов Хилсбрада и тем самым доказать свою ловкость.$b$bС уважением,$b$bФахрад.','','','','','',''),
(6981,'Светящийся осколок','Отправляйтесь в Кабестан и найдите там кого-нибудь, кто сможет вам рассказать об этом светящемся осколке.$B$BЗатем отнесите осколок туда, куда вас направят.','Блестящий осколок ярко-зеленый, без примесей, но под поверхностью можно видеть что-то похожее на клубы дыма. Оторвать взгляд от этих узоров в глубине невозможно, но в то же время вы осознаете какое-то беспокойство.$B$BПожалуй, стоит поискать в Кабестане кого-нибудь, кто может знать больше об этом странном осколке.','Поговорите с кем-нибудь в Кабестане о светящемся осколке.','','','','',''),
(7791,'Пожертвование: шерсть','','','','','','','',''),
(7802,'Пожертвование: шерсть','','','','','','','',''),
(7905,'Ярмарка Новолуния','Передайте сертификат на призовой купон Гельвасу Угольному Шлюзу на ярмарке Новолуния.','Грядет Ярмарка Новолуния! Готовься испытать все ее чудеса и радости, когда она прибудет в наш город!$B$BЕсли ты поторопишься, то сможешь обменять этот сертификат на призовой купон! Надо только передать сертификат Гельвасу Угольному Шлюзу в ярмарочном лагере.$B$BСейчас ярмарка стоит рядом со Златоземьем, в Элвиннском лесу. Не упусти шанса! Отправляйся прямо сегодня!','','','','','',''),
(78150,'Покровитель библиотеки','','','','','','','',''),
(79008,'...та записка, которую вы нашли','Надпись на обгоревшем клочке бумаги – ваша единственная подсказка.','<Вы обнаруживаете пепелище, догорающие угли которого уже почти погасли.\n\nСреди разбросанных припасов вам попадается обожженный клочок бумаги.>\n\n"Не все, что горит, пропадает навечно. Найди земли близнецов, а в них – нужное место".','','','','','',''),
(79092,'Научные записи верховного мага Теокрита','','','','','','','',''),
(79192,'Каменные ступени','Вы отрываете записку от доски и читаете неразборчивые строки.','Записка начинается словами: "В отчете о задании сказано, что оба совершали поставки, связанные с новой чумой. Мне кажется, с аптекарями нередко происходят подобные несчастные случаи. Если хочешь поговорить в безопасном месте, найди мое уютное пристанище в горах между Степями и Пустошами".','','','','','',''),
(79974,'Мокрая работа','Вы вытаскиваете из земли сумку посланника и отряхиваете ее. Рядом с припасами в ней лежит пергамент.','"Всегда стараюсь держать поблизости еще один тайник на случай, если придется внезапно бежать.\n\nСклоны этой горы так красивы, словно их вырезали из водопадов времени.\nИщи гнездо орла. Именно оно тебе нужно".','','','','','',''),
(79980,'По тревоге','Узнайте, что ждет впереди.','"Неплохо, да? Раз ты это читаешь, мой тайник еще не нашли. Сделай сто шагов на север и не переломай ноги, спускаясь по крутому склону. Содержимое тайника позволит тебе протянуть еще какое-то время".','','','','','',''),
(86574,'Доставка припасов в Когтистые горы','Добудьте у величавых виверн $1oa |4связку:связки:связок; припасов Каменного Когтя и доставьте их хозяйке таверны Фаралии.','<На теле несчастной видны следы многочисленных ударов величавых виверн. Рядом лежит помятый пустой мешок, а курьер сжимает в руке лишь маленькую записку, благодаря которой можно понять, что было потеряно: груз, предназначавшийся для хозяйки таверны Фаралии на пике Каменного Когтя.>\n\n<Виверны, должно быть, унесли связки припасов, чтобы выстелить ими свои гнезда.>','','','','','',''),
(86614,'Серебряные волны','Верните серебряную заколку с монограммой владелице.','<Среди рыболовных снастей в обломках лежат ржавые крючки, поврежденные катушки проволоки и слегка окислившаяся, но богато украшенная серебряная заколка для волос с монограммой Х.Р.>','','','','','',''),
(88756,'Взрывоопасное возвращение','Верните $1oa |4груз:груза:грузов; украденной взрывчатки из лагерей дворфов Черного Железа.','У дворфов Черного Железа есть несколько лагерей к востоку отсюда, на Зловещем холме. Они украли кучу взрывчатки с нашей стройплощадки и сложили ее в своих палатках.\n\nМне незачем говорить, какой переполох устроят дворфы Черного Железа, если им дать бочку пороха!\n\nЯ знаю, что эти ребята опасны, но нам надо вернуть бочки. Их можно отличить от других по красным меткам. Нельзя, чтобы они остались у клана Черного Железа!','','','','','',''),
(91732,'Хорошая сталь','Соберите 4 шахтерских инструмента в Яшмовой шахте, а затем вернитесь к Хагару Лоу на лесопилку Восточной долины.','После войны хорошей стали не хватает, и из-за этого инструменты наши не те, что прежде. Шахтеры в Яшмовой шахте работали отличными стальными кирками, и некоторые из них наверняка еще лежат где-то в глубине. Можешь достать мне хоть немного? А я попробую что-нибудь сделать из этой стали.','','','','','',''),
(91775,'Вернуть книги','Найдите 6 пропавших книг, а также книгу "Элементали – это весело" и верните их маршалу Дугхану.','Когда будешь исследовать рудник Подземных Глубин, постарайся найти там книги брата Пакстона. Его особенно беспокоит судьба работы под названием "Элементали – это весело". Он полагает, что с ее помощью даже кобольды смогут призвать себе слугу-элементаля. Будь $gосторожен:осторожна; – нижние ярусы рудника довольно опасны. Лучше захвати с собой друзей.\n\nИ возьми вот эту сумку! В ней найденные книги будут в безопасности.','','','','','',''),
(92401,'Тревожная просьба','Расследуйте исчезновение Эдварда Хартвивера в руинах Лордерона.','Мой муж Эдвард...\n\nОн каждую неделю ходит на кладбище в руинах Лордерона, но в этот раз не вернулся. Наш сын погиб, когда Артас сровнял город с землей, и мой милый Эдвард до сих пор винит себя и убивается из-за того, что мы так и не нашли его тело. Я отговаривала его от поисков в опасных руинах, но он отказывается сдаваться. Я стараюсь не переживать, но прошло уже несколько дней.\n\nМне в руинах не уцелеть, но если ты $gсогласен:согласна;, помоги – мне просто необходимо узнать о судьбе мужа.','Расследуйте исчезновение Эдварда Хартвивера в руинах Лордерона.','','','','',''),
(92415,'Помни, что я люблю тебя','Принесите запятнанное кровью письмо попечительнице сирот Найтингейл в Штормград.','<Рваный и запачканный пергамент, долгое время пролежавший на кишащем нежитью кладбище, сильно повредился. В нем говорится о пропавшем ребенке из семейства Хартвивер. Возможно, попечительница сирот из Штормграда что-то знает об этом.>','','','','','',''),
(92421,'Правосудие Света','Добудьте $1oa |4сохранившуюся конечность:сохранившиеся конечности:сохранившихся конечностей; в руинах Лордерона и принесите их Морбину Погибель Света в Подгород.','Мой долг как паладина-Отрекшегося – исполнять волю Темной Госпожи и заботиться о нашем народе. Нам повезло, ведь у нас есть возможность исполнить обе задачи разом.\n\nНад Подгородом до сих пор в огромных количествах бродят воины Плети. Мы пытаемся отвоевать наши земли, но постоянно теряем солдат, а разлагающуюся плоть нельзя просто зашить. Но можно заменить.\n\nЖаль, что наш славный капитан Гарек Бандарион больше не с нами, но я знаю, чего бы он хотел – завершить начатое и исцелить наш народ. За Лордерон!','','','','','',''),
(92422,'Гнев Рат''маэля','Убейте Рат''маэля на руинах Лордерона по поручению стража смерти Кристофа из Брилла.','Пришли вести с обзорной площадки озера Лордамер, расположенной глубоко в руинах Лордерона. Улицы и кладбище окутаны зловещим туманом, что позволяет тамошней Плети действовать скрытно.\n\nРазведчики докладывают, что армию нежити постоянно пополняет некромант по имени Рат''маэль. Промедление смерти подобно, $n.\n\nЗови всех своих союзников и иди на помощь к Отрекшимся. Изгони это существо из наших земель.','','','','','',''),
(92456,'Зеленый образец','Найдите в Даларане пропитанный Скверной цветок по просьбе Шайламиир из Штормграда.','Раз уж ты $gрешил:решила; мне докучать, пусть от тебя будет хотя какая-то польза. У меня есть одно дело.\n\nХотя Даларан город магов, его жители проявляют неожиданный интерес к ботанике. Кирин-Тор не привечает посторонних, но мне бы очень хотелось получить образец их растений, насыщенных маной.\n\nТы явно чувствуешь себя в своей тарелке там, где тебе не рады. Может быть, тебе удастся пробраться в город. Если сумеешь это сделать, принеси мне что-нибудь из тамошнего центрального сада.','','','','','',''),
(92745,'Состояние рудников','Убейте 4 кобольдов-землекопов на руднике Янго и 6 шахтеров из стаи Речной Лапы на прииске на Золотом Берегу.','В образцах колодезной воды, которые ты $gсобрал:собрала;, содержатся ядовитые металлы! Если сейчас же не положить конец этой порче, на здешних полях не будет урожаев еще несколько десятилетий.\nБратство Справедливости захватило рудники Западного края и заставляет местных обитателей добывать ресурсы. Сорви их планы, убив шахтеров на руднике Янго на севере и прииске на Золотом Берегу на западе.','','','','','',''),
(92753,'Разрушения в Мертвых копях','Найдите горн, спрятанный в Мертвых копях, и разместите рядом с ним особо разрушительную взрывчатку. Затем найдите Альбу Светлая Луна у выхода из Мертвых копей.','Скорее всего, источником яда является какой-то крупный металлургический горн. Проберись в Мертвые копи и найти этот горн, а затем заложи взрывчатку.\nЯ буду ждать тебя в холмах за Луноречьем. Мы детонируем взрывчатку, когда ты вернешься. Надеюсь, когда этот горн будет уничтожен, земля сможет исцелиться.','','','','','',''),
(94214,'Задание мастера: зелье защиты от темной магии','Добудьте предметы из заказа и доставьте в место, отмеченное на карте. Чтобы получить плату, нужно иметь при себе это свидетельство.','<В записке, написанной выцветшими чернилами, содержится заказ на $2oa |4порцию:порции:порций; зелья защиты от темной магии, а также сведения о том, куда все нужно доставить, и об оплате. Снизу указано, что этот заказ можно передавать другим.>','','','','','',''),
(94499,'Зов Воды','Наполните пустой красный бурдюк для воды из водопада Каменной Стражи неподалеку от мурлоков-следопытов и отнесите воду Гервдане Саэгрунд в Болотину.','Озеро Безмолвия поит все Красногорье, но к тому времени как его воды обрушиваются в водопаде Каменной Стражи, к ним что-то примешивается. Местные мурлоки – здоровенные и странные твари, совсем не такие, как те, которых можно найти здесь или у озера Лок. К счастью для горожан, они почти не отходят от подножия водопада.\n\nПринеси мне образец вод у того старого форта. Хочу разобраться, что их загрязняет, – яд или что-то еще.','','','','','',''),
(95189,'Герб Лордерона','Принесите герб Лордерона леди Дене Кеннеди в Штормград.','<Истертый герб с символом Лордерона. После падения королевства уцелело так мало реликвий, что кто-нибудь в Штормграде наверняка заинтересуется этим предметом.>','','','','','','Принесите герб Лордерона леди Дене Кеннеди в Штормград.'),
(95195,'Окровавленный знак отличия','Соберите $1oa |4окровавленный знак:окровавленных знака:окровавленных знаков; отличия и принесите их генералу Маркусу Джонатану.','<Похоже, этот старый знак отличия Альянса принадлежал солдату Лордерона. В этих руинах наверняка полно таких медалей. Выжившие родственники солдат будут благодарны их получить.>','','','','','',''),
(95204,'Герб Лордерона','Принесите герб Лордерона Оран Змеиные Кольца в Подгород.','<Истертый герб с символом Лордерона. После падения королевства уцелело так мало реликвий, что кто-нибудь в Подгороде наверняка заинтересуется этим предметом.>','','','','','',''),
(95216,'Новая чума','Добудьте крайне токсичный штамм у Сухожвала в руинах Лордерона для Теодора Гриффса из Подгорода.','Добро пожаловать в самый главный орган Подгорода: Квартал аптекарей! Здесь мы экспериментируем с самыми заразными и экзотическими веществами на всем Азероте.\n\nТы $gзастал:застала; меня в хорошем настроении, так что я позволю тебе поучаствовать в моем новом расследовании. Похоже, в руинах над нашим прекрасным городом завелся крайне ядовитый членистоног. Говорят, его токсин разъедает даже плоть нежити. Разве не восхитительно?\n\nНужно убедиться в достоверности этих слухов. Если эта тварь заразит тебя своим смертельным ядом, приходи ко мне – я возьму образец.','','','','','',''),
(95250,'Омерзительные создания','Добудьте голову барона в руинах Лордерона и принесите ее капитану Труману.','Что тебе нужно, |3-6($r)? Не видишь, у нас тут война?\n\nМой господин уже бросился в бой, а мне велел оставаться здесь. Но прошло уже довольно много времени.\n\nТы небось и десяти минут в бою не продержишься, но если тебе не хватает ума придумать себе занятие, то поищи моего господина, главнокомандующего. Он самый высокий и статный герой, какого тебе когда-либо доводилось видеть, так что ты его сразу узнаешь.','','','','','',''),
(95646,'Ужас на нагорье','Убейте Ужас нагорья на раскопках и принесите его корень Ретилю Стражу Природы в Болотину.','На этих солончаковых болотах есть большой источник пресных южных вод. Мне больно это осознавать, но я корнями чувствую порчу, просачивающуюся сквозь горное ущелье, откуда они появляются.\n\nСущества там, как и в наших низинах, реагируют на скверну куда острее. Соль моря не закаляла их с самого детства, и потому им нечего противопоставить подобному злу.\n\nОтправляйся на нагорье и принеси мне корень Ужаса нагорья.','','','','','',''),
(95647,'Потерявшийся травник','Найдите Ардина Грассмана на раскопках.','У моего мужа, Ардина, редкий дар чувствовать природу. Ему никакая вершина нипочем, лишь бы собрать травы и цветы, нужные мне для алхимии. Наши полки и кладовая никогда не пустеют.\n\nТолько вот теперь он, боюсь, попал в беду. Недавно мы повстречали экспедицию, которая искала, где бы пополнить припасы. Они говорили, среди прочего, об исполинских травах, каких никто прежде не видывал. Именно на них он и отправился посмотреть своими глазами. Его нет уже слишком долго!\n\nЯ буду благодарна, если ты его поищешь.','','','','','',''),
(95772,'В поисках Поющего Клинка','Поищите брата Дорина Поющий Клинок, Дэвина, на раскопках Вельгара.','Братишка все зазывал меня отправиться с ним в Болотину вместе с копателями из Лок Модана. Говорил, мол, собираются они в холмы, куда еще ни один дворф сроду не ступал. Раскопки какие-то затеяли.\n\nЯ бы пошел, да только уже взялся пояса перековывать, не успевал к сроку.\n\nДэвин мне обычно пишет, когда куда-то отправляется, а тут ни словечка я от него не получил. На душе от этого как-то неспокойно.\n\nКоли пойдешь в те края, не поищешь заодно и братишку моего?','','','','','',''),
(95810,'Носитель утерянной реликвии','Отнесите реликвию титанов геологу Вельгару на раскопки в Болотине.','Вы поднимаете обломок каменно-механического автоматона. На ощупь он не похож ни на что, с чем вам доводилось сталкиваться ранее – это какой-то материал неизвестного состава. Вы бы скорее отнесли это к категории артефактов, чем мусора.\n\nВозможно, геолог Вельгар с раскопок расскажет об этой реликвии что-нибудь полезное.','','','','','',''),
(95999,'РАЗЫСКИВАЕТСЯ: Испепелитель Гар''им','Отнесите сломанный посох Испепелителя Гар''има мировому судье Соломону в Приозерье.','Разыскивается: Испепелитель Гар''им, предводитель армии орков в долине Ренда. Предположительно работает с кланом Черной Горы в крепости Каменной Стражи.\n\nБерегитесь Испепелителя Гар''има: он и его темные чародеи крайне опасны. Смельчак, что предоставит доказательство гибели Испепелителя Гар''има мировому судье Соломону, получит щедрую награду.','','','','','',''),
(96138,'Лук Меррика','Победите $1oa |4воина:воинов:воинов; и $2oa |4надсмотрщика:надсмотрщиков:надсмотрщиков; из клана Дробящего Кулака, а затем вернитесь к Шире Фон-Инди в Темнолесье за дополнительной информацией.','Лук, оставленный духом Меррика Вэлора – знаменитого дозорного, гордо защищавшего дороги от подступающих врагов.\n\nСудя по тому, что дух Меррика все еще бродит по дороге, можно предположить, что у него есть незавершенное дело – уничтожить захватчиков возле его дома на Вороньем Холме. Вероятно, огры к югу от города не дают ему упокоиться.','','','','','',''),
(96139,'Семейство Вэлор','Найдите что-нибудь интересное на Вороньем Холме и вернитесь к Шире Фон-Инди в Темнолесье.','В эти темные времена мы должны знать и помнить наших героев не хуже, чем наших врагов. Темнолесья бы не было, если бы не подвиги отважной леди Алтеи и тех смельчаков, что сложили головы на Вороньем Холме.\n\n$gЧитал:Читала; ли ты о Вороньем Холме? Нет? Я так и думал. История этого места была забыта, стерта с лица земли вместе с его обитателями. Даже в моей огромной библиотеке почти нет записей о нем.\n\nЕсли найдешь что-либо касающееся Вороньего Холма, принеси это мне, пожалуйста. Его жители заслуживают того, чтобы их помнили.','','','','','',''),
(96393,'Вторжение в Старый Стальгорн','Войдите в Чертоги танов под Старым Стальгорном и добудьте голову Даргена Сокрушающий Молот.','Собери союзников и вместе спуститесь в пещеры под Старым Стальгорном. Там войдите в Чертоги танов и пробивайтесь к нижним склепам.\n\nПамять у меня уже не та, что прежде, но вроде одно имя я еще не забыл – Дарген Сокрушающий Молот. Скорее всего, там он за главного. Сними его голову с плеч и принеси королю Магни Бронзобороду.\n\nА, и передай заодно, что его старый друг Фарсен желает ему доброго здравия!','','','','','',''),
(97005,'Чол''арук Стервятник','Принесите голову Чол''арука Бэйнхему в Степях.','Ходят слухи, что в пещере на северо-западе отсюда, на Тернистом холме, поселилось громадное чудище. Свинобразы из племени Иглогривых зовут его Чол''арук, или "Стервятник". Говорят, он такой огромный, что может целиком проглотить орка.\n\nМало кто верит в такие россказни, но я уверен, что это правда... потому что и сам сражался с подобным чудовищем. Эта тварь должна умереть – во имя моих товарищей, которых я тогда потерял.\n\nСобери могучих союзников и отыщи логово Чол''арука. Убей эту мерзкую тварь и принеси мне ее голову.','','','','','',''),
(97288,'Неизбывные мучения','Принесите чудовищную голову мастеру аптекарю Фаранеллу в Подгород.','<Когда существо обрушивается на землю, его голова отделяется от тела. Похоже, ее присоединяли уже несколько раз, и с каждым разом связь становилась слабее.\n\nКто-нибудь в Подгороде наверняка знает что-то об этом необычном поганище.>','Принесите чудовищную голову кому-нибудь в Подгород.','','','','',''),
(97894,'Дела в Аубердине','Проведайте Горбольда Сталерука в Аубердине на Темных берегах.\n\nБоргус обмолвился, что туда можно попасть на корабле, отбывающем из порта Штормграда с самого южного причала.','Душевно рад познакомиться! Звать меня Боргус, я из единственной и неповторимой семьи Сталеруков. Со Сталеруками ты всегда можешь рассчитывать на выгодную и честную сделку!\n\nНесколько недель назад мой брат Горбольд открыл торговую лавку в Аубердине. На снабжении тамошних кораблей можно целое состояние сколотить, уж поверь мне! Вот уж повезло так повезло.\n\nС тех пор я не получал от него весточки – может, заглянешь его проведать, если тебе будет по пути?\n\nТут в порту новый корабль стоит, который идет как раз туда. Ступай на самый южный причал, ты его точно не пропустишь!','Сядьте на корабль до Аубердина и там разыщите Горбольда Сталерука.','','','','',''),
(97914,'Новые горизонты','Принесите письмо Тандриса Баросу Алекстону в Штормград.\n\nТандрис упоминал, что туда можно попасть на корабле из Аубердина.','Аубердин – непримечательное место, |3-6($c). Под дарнасскими ветвями никому до него нет дела. Большинство обсуждает лишь руины некогда процветавших городов, разрушенных Расколом – Амет''Аран, Башал''Аран и... Латар''Лазал.\n\nНо Аубердин продолжает существовать в их тени.\n\nЯ хочу, чтобы о нашей работе узнали. Недавно к нам начал ходить корабль из королевства Штормград, доставляющий к нашим берегам путешественников и припасы. Прошу, отправляйся на этом корабле в Штормград и отнеси это письмо человеку по имени Барос Алекстон.\n\nПусть мир узнает о нашем доме.','','','','','',''),
(97916,'Основы походной жизни: кузнечное дело','Поговорите с кузнецом Аргусом в Златоземье, чтобы показать свои навыки и научиться создавать предмет для лагеря, соответствующий вашей профессии.','Так ты $gрешил:решила; стать кузнецом? Отличный выбор, если хочешь, чтобы твои клинки никогда не затупились.\n\nСдается мне, я знаю кое-кого, кто может тебе помочь и научить создавать круг для заточки. Установишь такой у себя в лагере – отбоя не будет от воинов и разбойников, которым надо заточить оружие.','Отыщите лагерь охотников','','','','',''),
(97917,'Основы походной жизни: наложение чар','Поговорите с Бетти Квин в Штормграде, чтобы показать свои навыки и научиться создавать предмет для лагеря, соответствующий вашей профессии.','Зачаровыватели делают все лучше, и их привечают в любом походном лагере.\n\nСдается мне, я знаю кое-кого, кто может научить тебя создавать зачарованную лютню для своего лагеря. Развлечения – очень важная штука на отдыхе, а эта магическая вещица поможет тебе достойно встречать любые проблемы в пути.','Отыщите лагерь охотников','','','','',''),
(97920,'Основы походной жизни: рыбная ловля','Поговорите с Ли Брауном в Златоземье, чтобы показать свои навыки и научиться создавать предмет для лагеря, соответствующий вашей профессии.','Ты, может, об этом не $gзадумывался:задумывалась;, но навыки рыбной ловли могут очень пригодиться в лагере.\n\nСдается мне, я знаю кое-кого, кто может научить тебя создавать аквариум для лагеря. Он порадует тебя и других искателей приключений, ведь даже простые радости могут сделать нас сильнее. Уверена, ты и $gсам:сама; в этом убедишься.','Отыщите лагерь охотников','','','','',''),
(98072,'Кроколиски в небесах','Принесите 8 безупречных алых чешуек Джеймсу Халлорану в Гавань Менетилов.','Да ты $gнастоящий труженик:настоящая труженица;! У меня есть еще одна просьба, если ты не прочь взяться за работу поопаснее.\n\nТорговля кроколисками приносит стабильный доход, но это мелочь по сравнению с тем, что можно выручить за драконью чешую. За мешок чешуи дракончиков заплатят солидные деньги.\n\nЯ их называю небесными кроколисками! Моему ученику ни за что к ним не подобраться, зато эта работа, похоже, как раз по твоей части!\n\nДракончиков можно найти далеко на востоке, вдоль Зеленого Пояса. Но будь настороже – в тех холмах рыскают злобные орки!','','','','','',''),
(98189,'Возвращение статуэтки','Отнесите статуэтку Менетила капитану Крепкому Кулаку в крепость Менетилов.','Невероятно... Какая красота!\n\n"Слепая принцесса" должна была доставить это в Гавань Менетилов, прежде чем произошла трагедия. Мы были так близки!\n\nПолагаю, капитан Крепкий Кулак должен был подписать нужные документы в крепости Менетилов позади нас. Почему бы тебе не оказать нам всем честь и не закончить работу?','','','','','',''),
(98190,'Друг семьи','Отнесите статуэтку Менетила верховному лорду Болвару Фордрагону в крепость Штормграда.','Тебе следует немедленно отправиться с этим в Штормград. Как бы я ни гордился тем, что крепость и гавань носят имя короля Теренаса Менетила II, это место – лишь небольшой тихий уголок посреди настоящей бури врагов. Здесь просто-напросто небезопасно.\n\nВ частности, клан Драконьей Пасти многим бы пожертвовал, чтобы завладеть чем-то подобным... Боюсь даже представить, что бы они сделали с такой ценностью.\n\nПравилами субординации можешь в этот раз пренебречь, $Gпарень:милая;. Отправляйся прямиком к верховному лорду Фордрагону. Он знает, где следует хранить такой предмет.','','','','','',''),
(98191,'Друг семьи','Отнесите статуэтку Менетила лорду Грейсону Тенелому в Собор Света.','Король Теренас был хорошим человеком. Набожным. Народ любил его, и именно ему наш Альянс обязан своим существованием.\n\nИрония состоит в том, что он был очень скромным и терпеть не мог подобные памятные предметы. Поэтому их так мало. И лишь малая часть уцелела после падения Лордерона.\n\nПохоже, в этой статуэтке собралась сила Света. Лучше всего хранить ее в Соборе Света на Соборной площади, в самом центре города. Отнеси ее лорду Грейсону Тенелому.','','','','','',''),
(98197,'Трофеи войны','Добудьте для Валстага Сталезуба $1oa ед. каз-моданской древесины и $2oa ед. каз-моданского железа в Гавани Менетилов.','Эту гавань Старая Орда построила как плацдарм для морского вторжения в Хилсбрад. Так она смогла полностью обойти оборону Лордерона!\n\nСколько же жизней унесла война...\n\nЧто еще хуже, тот флот был построен из материалов, украденных из Каз Модана!\n\nМного чего осталось в гавани после того, как адмирал Праудмур разгромил захватчиков и отстроил это место для Альянса. Нам понадобятся эти материалы, чтобы укрепить оборону города, когда клан Драконьей Пасти перейдет в наступление.','','','','','',''),
(98208,'Небесный цветок','Добудьте Норд''эль для Силессы Шепот Сумрака в Гавани Менетилов.','Я прибыла в Гавань Менетилов из Аубердина близ великого древа Тельдрассила, чтобы вернуть цветок, имеющий огромное значение для моего народа.\n\nМного лун назад здесь потерпел крушение наш корабль "Орлик", входивший в состав Третьего кул-тирасского флота. На нем перевозили цветок, известный как Норд''эль – или "Небесный цветок" на вашем языке. Он распустился при полной луне на горе Хиджал, которая когда-то была для нас домом.\n\nПрошу, помоги мне его вернуть! Место кораблекрушения расположено к югу от города, но там обитают свирепые мурлоки-налетчики!','','','','','',''),
(98219,'Опозоренный лейтенант','Поговорите с лейтенантом Фарреном Оринелем в Южнобережье в предгорьях Хилсбрада.','Еще раз спасибо за безопасную доставку статуэтки, $n.\n\nМне нужна твоя помощь еще кое в чем. Есть один городской стражник, которого перевели на службу в Южнобережье, в предгорья Хилсбрада.\n\nЕго отец был моим другом, и хотя я не спорю, что его стоит научить уму-разуму... мне все же хочется, чтобы он добился успеха. Помощь кого-то вроде тебя была бы ему очень полезна.\n\nЕсли отправишься в ту сторону, то можешь сесть на корабль из Гавани Менетилов.','','','','','',''),
(98221,'Из пепла','Уничтожьте 4 комплекта планов нападения в лагере Злого Клыка по просьбе капитана Крепкий Кулак из крепости Менетилов.','В ходе Второй войны орки из клана Драконьей Пасти построили тут флот, намереваясь захватить Хилсбрад. И затея почти увенчалась успехом!\n\nИх разгромили красные драконы, и уцелевшие орки отступили далеко в горы. Однако они снова зашевелились в лагере к северо-востоку от крепости Менетилов.\n\nДун Альгаз – доказательство того, что они собираются снова развязать войну и попытаться завоевать эти земли. Найди их планы нападения, скопируй самые важные записи и уничтожь оригиналы. Нам нужно знать, где они нанесут следующий удар!','','','','','',''),
(98240,'Доставка багровых ящиков','Отнесите багровый ящик Ховину Мягкое Перо, который находится к востоку от Гавани Менетилов.','Вести о дракончиках быстро разлетелись, $n. У нас уже есть один заказ!\n\nЯ красиво его упакую, а ты отнесешь клиенту. Я все прекрасно понимаю, так что об услуге прошу в последний раз, обещаю!\n\nЭтот заказ сделал некий Ховин Мягкое Перо. К слову, для этого он отправил в город своего грифона с письмом! Пишет, что он находится чуть в стороне от восточной дороги, немного дальше области раскопок Вельгара, если тебе знакомы те места.','','','','','',''),
(98245,'Иголки из острых зубов','Добудьте $1oa |4резец:резца:резцов; острозуба для Ховина Мягкое Перо.','Даже не знаю, кого я ненавижу больше: проклятый клан Черного Железа, орков Драконьей Пасти или тех драконов, на которых они ездят.\n\n<Ховин сплевывает.>\n\nЯ намерен воздать негодяям по заслугам. Но нам понадобятся кое-какие припасы.\n\nЭти чешуйки дракончиков неплохо защитят от огненного дыхания, но их до невозможности трудно сшивать.\n\nХищные острозубы на гряде Ящеров к северо-востоку и в долине Солевого Тумана к северо-западу получили свое название не просто так. Их острые зубы должны легко пробить чешуйки.\n\nПринеси мне горсть их клыков.','','','','','',''),
(98246,'Непростые времена','Добудьте $1oa |4идеальное яйцо:идеальных яйца:идеальных яиц; острозуба для Ховина Мягкое Перо.','Чтобы претворить план в жизнь, мне понадобятся яйца. Глухоклюв надо как следует подкрепиться – я не собираюсь седлать озлобленного от голода грифона.\n\nЯйца должны быть первосортными, без трещин или еще каких изъянов.\n\nДобыть их можешь у острозубых ящеров – в их яйцах желтки размером с голову гнома. Этих зверюг можно найти на гряде Ящеров на северо-востоке и в долине Солевого Тумана на северо-западе.\n\nСобери-ка на всякий случай сразу дюжину.','','','','','',''),
(98247,'Транспортная этикетка','Доставьте транспортную этикетку кому-нибудь в "Азеротском торговом управлении" в Красногорье.','<На боку заполненного ящика наклеена порванная этикетка. Хотя имя адресата не сохранилось, на ней можно разобрать сведения о том, откуда был отправлен груз.\n\n"Собственность "Азеротского торгового управления". Пустые ящики и недоставленные грузы просим возвращать в наш торговый пункт у Трех Углов в Красногорье. Курьеров вознаградят за потраченное время и проделанный путь".\n\nРядом с текстом есть грубый набросок карты упомянутой местности.>','','','','','',''),
(98282,'Опасная алхимия','Добудьте нелопнувшую железу хищника в пещере Тельгена для Кейтлин Грассман в Гавани Менетилов.','Некоторые алхимические рецепты требуют ингредиентов, которые собирают, скажем так, в крайне небезопасных местах. И зачастую это всего лишь базовые травы! А есть такие ингредиенты, которые вообще добыть практически невозможно!\n\nПрежде чем я снова смогу отправиться в путь, мне нужно изготовить побольше противоядия. Честное слово, в этом болоте все ядовито. Как будто отрава пропитала саму землю!\n\nТы поможешь мне? Мне нужна ядовитая железа пауков из пещеры Тельгена далеко на юго-востоке. Но она должна быть неповрежденной, иначе по дороге обратно из нее выльется слишком много яда. Ты уж извини!','','','','','',''),
(98283,'Резчик-по-живому','Вернитесь с головой Резуна к Ретилю Стражу Природы в Зеленый Пояс.','Естественный ход вещей в природе этого края нарушен. Раньше хищные острозубы сдерживали разрастание леса. Теперь они живут в страхе перед своим вожаком, получившим имя из-за того, какую кровавую бойню он постоянно устраивает всюду, куда бы ни пошел.\n\nБоюсь, зверь сошел с ума от болезни, которую мы еще не полностью искоренили.\n\nЕго наверняка привлечет зараженная плоть больных медведей, обитающих у подножия гряды Ящеров на северо-востоке. Разбросай их внутренности в его логове.\n\nРезун непременно явится. Принеси мне его голову.','','','','','',''),
(98293,'Принудительное разоружение','Соберите $1oa ед. снаряжения Драконьей Пасти в Убежище Драконьей Пасти, а затем отнесите его капитану Крепкому Кулаку в крепость Менетилов.','Орки из клана Драконьей Пасти собирают самое разное оружие. Было бы разумно избавить их от этих запасов, прежде чем они смогут вооружить еще больше солдат.\n\nКапитана Крепкого Кулака в крепости Менетилов наверняка заинтересует возможность пополнить арсенал.','','','','','',''),
(98310,'Предвидение будущего','Используйте камень Гоаз рядом с Адосом, Модром, Голмом и Неру и принесите их сердца геологу Вельгару.','В Болотине обнаружены и другие, более крупные големы. На них выгравированы надписи "Адос", "Модр", "Голм" и "Неру", соответствующие недостающим частям найденной тобой скрижали Гоаз!\n\nГотов поспорить, что если мы добудем недостающие части, то узнаем о скрижали Гоаз еще больше!\n\nАдос ты найдешь у врат Драконьей Пасти на востоке, недалеко от Грим Батола. Модр находится прямо за Дун Модром на севере. Голм лежит под Грим Батолом, к востоку от Дун Альгаза. Неру ты найдешь за Зловещим холмом на северо-востоке.','','','','','',''),
(98386,'Лесопилка Альтера','Убейте $1oa |4крупного тарантула:крупных тарантулов:крупных тарантулов; и уничтожьте $2oa |4яйцо:яйца:яиц; тарантулов на лесопилке Альтера по просьбе штейгера Ослоу, который находится в Красногорье.','Орки, гноллы, мурлоки... Кажется, все только и делают, что пытаются помешать мне достроить мост к сроку. А теперь еще говорят, что на нашей лесопилке завелись тарантулы!\n\nЕсли хочешь немного подзаработать, сходи на лесопилку Альтера и изничтожь тамошних пауков. Она для меня совершенно бесполезна, если нельзя отправлять туда работников за грузами без риска для жизни.\n\nИ еще: если увидишь старика Альтера, скажи ему, что за ним теперь должок.','','','','','',''),
(98387,'Блокада Черной Горы','Принесите $1oa ед. украденного оружия и $2oa |4ящик:ящика:ящиков; с украденными припасами маршалу Маррису в Приозерье.','Без оружия воевать невозможно.\n\nОрки Черной Горы захватили большую часть этих земель, но их смелая тактика не лишена уязвимости.\n\nИди на юго-восток мимо крепости Каменной Стражи, найди их лагеря и уничтожь все оружие и припасы.\n\nПосмотрим, много ли эти орки навоюют, оставшись с голыми руками.','','','','','',''),
(98407,'Демонстрация силы','Добудьте $1oa |4шипастый ошейник:шипастых ошейника:шипастых ошейников; у твердозубов из стаи Красногорья для заместителя судьи Фелдона, который находится недалеко от Приозерья.','Раз уж гноллы так осмелели, что разбивают лагерь столь близко к людям, то неизвестно, на что еще они готовы пойти. Нам нужно их отпугнуть.\n\nЭтим тварям не хватает организованности, а больше всего они, похоже, ценят силу. Если убьем их вожаков и заберем какие-нибудь трофеи, то напомним этим гноллам, почему им следует сидеть на их холмах и не высовывать оттуда нос.\n\nЕсли ты повстречаешь их твердозубов, принеси мне их ошейники. Так мы заставим их дрожать в страхе перед мощью Альянса.','','','','','',''),
(98459,'Дефицит чести','Доставьте подарок Тома Барту Приливню в Гавань Менетилов в Болотине.','Барт Приливень – никудышный скряга, уж поверь!\n\nЗовет себя капитаном "Девичьей Чести". Да этот корабль проплыл в Танарисе не дальше брошенного камня! Он не капитан, а притворщик, который просто выиграл денег в покер и купил "Честь"!\n\nЕсли ты когда-нибудь окажешься в Гавани Менетилов в Болотине, передай ему это и скажи, что это от старины "Полурыба".\n\nКстати, отсюда прямо в гавань ходит корабль. Вторая остановка – твоя!\n\nИ помни, что в покере он жульничает!','','','','','',''),
(98461,'Безответная любовь','Отнесите записку Холли Таррелу Камнепряду, живущему неподалеку от Гавани Менетилов в Болотине.','Если ты собираешься покинуть Аубердин, мне бы пригодилась твоя помощь!\n\nМы с моим дорогим другом Таррелом были одноклассниками. О, во всем, что касалось раскопок, он был таким сообразительным! После окончания школы жизнь разбросала нас по миру: он отправился в Болотину, а я сюда, на Темные берега.\n\n<Холли вздыхает, затем слегка хмурится.>\n\nИзвини. Его жена... Меррин...\n\nВпрочем, неважно. Если окажешься в Болотине, можешь узнать, как у него дела? И, может, передашь ему это? Он, вероятно, где-то неподалеку от Гавани Менетилов. Туда ходит корабль.','','','','','',''),
(99130,'Заманчивое предложение','Добудьте $1oa |4сосуд:сосуда:сосудов; звериной крови и $2oa |4лепесток:лепестка:лепестков; закатнолиста для приманки на мурлоков, а затем вернитесь к Реми Повторюху в Златоземье.','У меня есть пара идей, как разобраться с мурлоками. И одна из них заодно поможет еще кое-кому.\n\nВ здешних усадьбах часто растет сорняк под названием закатнолист; в больших количествах его лепестки ядовиты для большинства животных. Если сделать из него приманку для мурлоков, глядишь, эти твари наконец научатся держаться подальше.\n\nЗаодно и поля фермерам расчистишь. Одни плюсы... одни плюсы.','','','','','','');
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`AreaDescription`,`PortraitGiverText`,`PortraitGiverName`,`PortraitTurnInText`,`PortraitTurnInName`,`QuestCompletionLog`,`VerifiedBuild`) SELECT t.`ID`,'ruRU',t.`LogTitle`,t.`LogDescription`,t.`QuestDescription`,t.`AreaDescription`,t.`PortraitGiverText`,t.`PortraitGiverName`,t.`PortraitTurnInText`,t.`PortraitTurnInName`,t.`QuestCompletionLog`,70862 FROM `tmp_ruru_quest_template_locale` t JOIN `quest_template` b ON b.`ID`=t.`ID` LEFT JOIN `quest_template_locale` l ON l.`ID`=t.`ID` AND l.`locale`='ruRU' WHERE l.`ID` IS NULL;
